INSERT INTO books (id,title,description,is_published,"order",created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-book$mmqz$,$mmqz$EMRCOG Recalls — July 2024 (Paper 02)$mmqz$,$mmqz$EMRCOG/MRCOG OB-GYN exam recall question bank.$mmqz$,true,999,now(),now()) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title,description=EXCLUDED.description,is_published=EXCLUDED.is_published,updated_at=now();
