INSERT INTO topics (id,chapter_id,title,description,is_published,"order",source,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$emrcog-jul2024-02-chap$mmqz$,$mmqz$MRCOG Recalls — July 2024, Paper 02$mmqz$,$mmqz$142 recall MCQs with explanations and figures, extracted from the July 2024 (Paper 02) EMRCOG recall set. Correct answers verified against the source; promotional content removed.$mmqz$,true,0,$mmqz$EMRCOG Recalls July 2024, Paper 02$mmqz$,now(),now()) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title,description=EXCLUDED.description,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q001$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$48 yr old on tamoxifen presented due to pain in loin, accidentally discovered to have an endometrial thickness of 22mm. How to evaluate?$mmqz$,$mmqz$[{"label": "A", "text": "Hysteroscopy with biopsy"}, {"label": "B", "text": "Pipelle biopsy"}, {"label": "C", "text": "Reassure"}, {"label": "D", "text": "Stop tamoxifen"}, {"label": "E", "text": "Evaluate if symptomatic."}]$mmqz$::jsonb,$mmqz$Evaluate if symptomatic.$mmqz$,$mmqz$For women on tamoxifen and symptoms of bleeding, urgent assessment is required, especially hysteroscopy and biopsy. Evidence does not support screening asymptomatic women with TVS and/or endometrial sampling; abnormal vaginal bleeding should prompt urgent investigation by TVS, hysteroscopy and endometrial sampling.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q1, p.1$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,$mmqz$[{"url": "/uploads/content-images/emrcog0224-q001-fig1.png", "caption": "Figure 1"}]$mmqz$::jsonb,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q002$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$Question describes a scenario of endometrial hyperplasia with atypia. Patient refuses surgery. What is the recommended follow up?$mmqz$,$mmqz$[{"label": "A", "text": "Endometrial biopsy at 3 months"}, {"label": "B", "text": "Endometrial biopsy at 6 months"}, {"label": "C", "text": "Endometrial biopsy at 3 monthly intervals, discharge after negative biopsy"}, {"label": "D", "text": "≥ 2 consecutive negative EBs at 3-month intervals, thereafter 6–12-monthly EB and review"}, {"label": "E", "text": "≥ 2 consecutive negative EBs at 3-month intervals"}, {"label": "F", "text": "≥ two consecutive negative EBs at 6-month intervals, thereafter annual EB and review."}]$mmqz$::jsonb,$mmqz$≥ 2 consecutive negative EBs at 3-month intervals, thereafter 6–12-monthly EB and review$mmqz$,$mmqz$Management of endometrial hyperplasia. For atypical hyperplasia (AH) managed non-surgically: ≥ two consecutive negative endometrial biopsies at 3-month intervals, thereafter 6–12-monthly EB and review.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q2, p.1$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,$mmqz$[{"url": "/uploads/content-images/emrcog0224-q002-fig1.png", "caption": "Figure 1"}]$mmqz$::jsonb,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q003$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$Question describes a scenario of endometrial hyperplasia with no atypia in an obese patient. How will you follow up?$mmqz$,$mmqz$[{"label": "A", "text": "Endometrial biopsy at 3 months"}, {"label": "B", "text": "Endometrial biopsy at 6 months"}, {"label": "C", "text": "Endometrial biopsy at 3 monthly intervals, discharge after negative biopsy"}, {"label": "D", "text": "≥ 2 consecutive negative EBs at 3-month intervals, thereafter 6–12-monthly EB and review"}, {"label": "E", "text": "≥ 2 consecutive negative EBs at 3-month intervals"}, {"label": "F", "text": "≥ two consecutive negative EBs at 6-month intervals, thereafter annual EB and review"}]$mmqz$::jsonb,$mmqz$≥ two consecutive negative EBs at 6-month intervals, thereafter annual EB and review$mmqz$,$mmqz$Endometrial hyperplasia without atypia (EH) with BMI ≥ 35 or treated with oral progestogens: ≥ two consecutive negative EBs at 6-month intervals, thereafter annual EB and review.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q3, p.1$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,$mmqz$[{"url": "/uploads/content-images/emrcog0224-q003-fig1.png", "caption": "Figure 1"}]$mmqz$::jsonb,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q004$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$Post-menopausal woman was started on combined HRT 6 months ago. She presents with persistent bleeding for the past 2 months, despite dose adjustments and increase in progesterone component. What is the next step?$mmqz$,$mmqz$[{"label": "A", "text": "TVS"}, {"label": "B", "text": "Pipelle biopsy"}, {"label": "C", "text": "Hysteroscopy guided biopsy"}, {"label": "D", "text": "Change to sequential HRT"}, {"label": "E", "text": "Stop HRT"}]$mmqz$::jsonb,$mmqz$TVS$mmqz$,$mmqz$Unscheduled bleeding on HRT: assess cancer risk factors and bleeding pattern, identify HRT regimen/duration/compliance, offer examination and investigations. With heavy/persistent bleeding, more than 6 months since starting HRT, or 1 major / 3 minor risk factors for endometrial cancer, arrange urgent TVS (within 6 weeks).$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q4, p.2$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,$mmqz$[{"url": "/uploads/content-images/emrcog0224-q004-fig1.png", "caption": "Figure 1"}]$mmqz$::jsonb,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q005$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$What is the risk of VTE in a postmenopausal woman on combined HRT for 5 years?$mmqz$,$mmqz$[{"label": "A", "text": "Additional 5 / 1000 women using HRT"}, {"label": "B", "text": "Additional 7 / 1000 women using HRT"}, {"label": "C", "text": "Additional 13 / 1000 women using HRT"}, {"label": "D", "text": "Additional 8 / 1000 women using HRT"}, {"label": "E", "text": "Additional 12 / 1000 women using HRT"}]$mmqz$::jsonb,$mmqz$Additional 7 / 1000 women using HRT$mmqz$,$mmqz$Risks associated with combined estrogen-progestogen HRT: venous thromboembolism (VTE) over 5 years use adds approximately 7 extra cases per 1000 women using HRT.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q5, p.3$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,$mmqz$[{"url": "/uploads/content-images/emrcog0224-q005-fig1.png", "caption": "Figure 1"}]$mmqz$::jsonb,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q006$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$How will you manage unscheduled bleeding in a patient on estrogel 1.5 mg and micronized progesterone 100 mg? She presented with bleeding within 6 months of starting the regimen.$mmqz$,$mmqz$[{"label": "A", "text": "Increase estrogen dose"}, {"label": "B", "text": "Change to sequential HRT regimen"}, {"label": "C", "text": "Change progesterone"}, {"label": "D", "text": "Increase progesterone dose to 200mg"}, {"label": "E", "text": "Reduce progesterone dose"}]$mmqz$::jsonb,$mmqz$Increase progesterone dose to 200mg$mmqz$,$mmqz$Unscheduled bleeding with sHRT/ccHRT within the first 6 months: options include increasing the micronised progesterone (MP) dose or changing to a synthetic progestogen, a 3-month trial of an additional progestogen on top of the current preparation, offering the 52 mg LNG-IUD, or changing to an oral preparation. Here, increase the progesterone dose to 200 mg.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q6, p.4$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,$mmqz$[{"url": "/uploads/content-images/emrcog0224-q006-fig1.png", "caption": "Figure 1"}]$mmqz$::jsonb,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q007$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$What is the most effective contraceptive for a patient on efavirenz?$mmqz$,$mmqz$[{"label": "A", "text": "Barrier contraceptive"}, {"label": "B", "text": "Progesterone only pills"}, {"label": "C", "text": "Desogestrel"}, {"label": "D", "text": "Combined hormonal contraceptive pills"}, {"label": "E", "text": "Copper T"}]$mmqz$::jsonb,$mmqz$Copper T$mmqz$,$mmqz$Efavirenz (EFV) is an enzyme-inducing NNRTI. Contraceptive effectiveness of CHC, POP and ENG-IMP could be reduced (use not advised). DMPA, LNG-IUD and Cu-IUD have no expected effect and need no extra precautions; the Cu-IUD (Copper T) is the most effective option.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q7, p.4$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,$mmqz$[{"url": "/uploads/content-images/emrcog0224-q007-fig1.png", "caption": "Figure 1"}]$mmqz$::jsonb,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q008$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$What is the most effective contraceptive for a patient on enzyme inducing anti-epileptic?$mmqz$,$mmqz$[{"label": "A", "text": "Barrier contraceptive"}, {"label": "B", "text": "Progesterone only pills"}, {"label": "C", "text": "Desogestrel"}, {"label": "D", "text": "Combined hormonal contraceptive pills"}, {"label": "E", "text": "Copper T"}]$mmqz$::jsonb,$mmqz$Copper T$mmqz$,$mmqz$DMPA and IUCD are both correct, but DMPA has an extra benefit in the epileptic patient. For enzyme inducers, DMPA, LNG-IUS and Cu-IUD have no expected effect on contraceptive effectiveness and need no extra precautions; the Cu-IUD is the most effective method of emergency contraception.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q8, p.5$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,$mmqz$[{"url": "/uploads/content-images/emrcog0224-q008-fig1.png", "caption": "Figure 1"}]$mmqz$::jsonb,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q009$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$How would you evaluate a structurally normal severe SGA fetus with normal uterine Doppler, anomaly scan showing ventricular dilatation?$mmqz$,$mmqz$[{"label": "A", "text": "Serological screening for CMV: CMV IgM and IgG with avidity"}, {"label": "B", "text": "B19V DNA or IgG seroconversion using an antenatal booking blood for parvovirus"}, {"label": "C", "text": "Screen for Toxoplasmosis + CMV"}, {"label": "D", "text": "Arrange for fetal echo"}, {"label": "E", "text": "Perform fetal echo + brain MRI"}, {"label": "F", "text": "Screen for toxoplasmosis."}, {"label": "G", "text": "Consider invasive diagnostic testing including a Microarray to detect microdeletions."}]$mmqz$::jsonb,$mmqz$Consider invasive diagnostic testing including a Microarray to detect microdeletions.$mmqz$,$mmqz$Invasive diagnostic testing should be offered in severely SGA fetuses with structural anomalies and considered in non-anomalous fetuses detected before 23 weeks of gestation, especially if uterine artery Doppler is normal. Analysis should include a microarray to detect microdeletions and microinsertions.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q9, p.6$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,$mmqz$[{"url": "/uploads/content-images/emrcog0224-q009-fig1.png", "caption": "Figure 1"}]$mmqz$::jsonb,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q010$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$How would you evaluate a structurally normal SGA fetus with normal uterine Doppler, normal karyotyping, USG showing mild ventricular dilatation?$mmqz$,$mmqz$[{"label": "A", "text": "Serological screening for CMV: CMV IgM and IgG with avidity"}, {"label": "B", "text": "B19V DNA or IgG seroconversion using an antenatal booking blood for parvovirus"}, {"label": "C", "text": "Screen for Toxoplasmosis + CMV"}, {"label": "D", "text": "Arrange for fetal echo"}, {"label": "E", "text": "Perform fetal echo + brain MRI"}, {"label": "F", "text": "Screen for toxoplasmosis"}]$mmqz$::jsonb,$mmqz$Serological screening for CMV: CMV IgM and IgG with avidity$mmqz$,$mmqz$Karyotyping normal. Serological screening for congenital CMV (and toxoplasmosis) should be offered in severe SGA, as fetal infections are responsible for up to 5% of SGA fetuses.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q10, p.7$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,NULL,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q011$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$Postpartum patient on antiepileptic (lamotrigine). The dose was increased in pregnancy. What is the advice regarding her dose modification?$mmqz$,$mmqz$[{"label": "A", "text": "Within 10 days"}, {"label": "B", "text": "Review in 4 weeks"}, {"label": "C", "text": "Review in 8 weeks"}, {"label": "D", "text": "Continue medications"}, {"label": "E", "text": "Continue pre-pregnancy antiepileptic dose"}]$mmqz$::jsonb,$mmqz$Within 10 days$mmqz$,$mmqz$If the AED dose was increased in pregnancy, it should be reviewed within 10 days of delivery to avoid postpartum toxicity. The increase should be clearly documented, with a plan to liaise with the neurological team to taper the dose in the first 10 days after delivery. If symptoms of AED toxicity develop in the puerperium (e.g. drowsiness, diplopia or unsteadiness), urgent neurological review is needed.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q11, p.7$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,NULL,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q012$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$What is the suggested time to discontinue etanercept during pregnancy?$mmqz$,$mmqz$[{"label": "A", "text": "30-32 wks"}, {"label": "B", "text": "21-22 wks"}, {"label": "C", "text": "26-28 wks"}, {"label": "D", "text": "28-32 wk"}]$mmqz$::jsonb,$mmqz$30-32 wks$mmqz$,$mmqz$Accumulation of anti-TNF agents in the neonate (Table 2). Etanercept has a half-life of ~4 days and a low cord blood to maternal serum concentration (3.6–7.4%); suggested gestation to discontinue is 30–32 weeks.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q10 (etanercept), p.7,8$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,$mmqz$[{"url": "/uploads/content-images/emrcog0224-q012-fig1.png", "caption": "Figure 1"}]$mmqz$::jsonb,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q013$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$Patient had IUFD at 4 days after her EDD. Baby weighed 2.6 kg. She denied postmortem examination. External features of the baby appeared normal on examination. What could be the most probable cause of IUFD?$mmqz$,$mmqz$[{"label": "A", "text": "Congenital anomaly"}, {"label": "B", "text": "Cord accident"}, {"label": "C", "text": "Placental dysfunction"}, {"label": "D", "text": "Karyotype anomalies"}]$mmqz$::jsonb,$mmqz$Placental dysfunction$mmqz$,$mmqz$Parents should be advised that no specific cause is found in almost half of stillbirths. An abnormal result might not be linked to the IUFD but rather be simply an incidental finding. Tests should be directed to identify scientifically proven causes of late IUFD. Commonly associated antepartum conditions include congenital malformation, congenital fetal infection, antepartum haemorrhage, pre-eclampsia and maternal disease such as diabetes mellitus. Common causes of intrapartum death include placental abruption, maternal and fetal infection, cord prolapse, idiopathic hypoxia–acidosis and uterine rupture.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q11 (IUFD), p.8$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,NULL,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q014$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$Asthmatic patient presented in labour. In view of poor control, she was started on prednisolone 5mg since 3 weeks back. What is recommended steroid cover for her during labour?$mmqz$,$mmqz$[{"label": "A", "text": "Give IV hydrocortisone during labour"}, {"label": "B", "text": "Increase prednisolone till respiratory medicine specialist consultation"}, {"label": "C", "text": "Give IV hydrocortisone only if she is planned for CS"}, {"label": "D", "text": "Continue prednisolone 5mg oral and offer hydrocortisone IV during labour"}]$mmqz$::jsonb,$mmqz$Continue prednisolone 5mg oral and offer hydrocortisone IV during labour$mmqz$,$mmqz$For adrenal insufficiency or those taking long-term oral steroids (equivalent to 5 mg or more prednisolone daily for more than 3 weeks): for women planning a vaginal birth, continue their regular oral steroids and give IV hydrocortisone; for women having a planned or emergency caesarean section, continue their regular oral steroids and give IV hydrocortisone when starting anaesthesia.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q12, p.8,9$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,NULL,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q015$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$What is the recommended fluid management in a patient with pulse 120/min, BP 90/60 mmHg presenting with diabetic ketoacidosis?$mmqz$,$mmqz$[{"label": "A", "text": "1 l normal saline in 1hr"}, {"label": "B", "text": "5 litre NS in 1 hr"}, {"label": "C", "text": "1 l dextrose normal saline in 1 hr"}, {"label": "D", "text": "0.9% normal saline 50 ml/kg/hr"}, {"label": "E", "text": "Several options mentioning various combinations"}]$mmqz$::jsonb,$mmqz$1 l normal saline in 1hr$mmqz$,$mmqz$Fluid replacement should be commenced by infusing isotonic saline (0.9%), as most patients have a negative fluid balance of about 100 ml/kg of body weight. This represents a total fluid deficit of approximately 6–10 l. The IV infusion should be started at 10–15 ml/kg/h in the first hour, after which the rate should be adjusted according to the haemodynamic status of the patient, guided by monitoring of blood pressure, urine output and central venous pressure in selected cases. When blood glucose falls below 14 mmol/l (250 mg/dL), add dextrose 10% 125 ml/hour to the ongoing saline IV fluid therapy.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q13, p.9$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,$mmqz$[{"url": "/uploads/content-images/emrcog0224-q015-fig1.png", "caption": "Figure 1"}]$mmqz$::jsonb,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q016$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$In an ongoing CPR on a collapsed type 1 diabetic patient, results of blood work show blood glucose at 4 mmol. She was at 23 wk GA and felt cold and clammy before the collapse. What is the next management?$mmqz$,$mmqz$[{"label": "A", "text": "IM adrenaline"}, {"label": "B", "text": "Glucose infusion"}, {"label": "C", "text": "IV adrenaline"}, {"label": "D", "text": "IM glucagon"}]$mmqz$::jsonb,$mmqz$Glucose infusion$mmqz$,$mmqz$Advise pregnant women with diabetes who are taking insulin to maintain their capillary plasma glucose level above 4 mmol/litre. Common, reversible causes of maternal cardiopulmonary arrest (the 4 H's and 4 T's) should be considered throughout the resuscitation process. Emergency treatment of hypoglycaemia is chosen according to the condition of the patient: if conscious and able to swallow give oral fast-acting carbohydrate (Step A); if unconscious/fitting/unable to swallow, stop any IV insulin and give 10% glucose infusion 200 ml over 10 mins (or 20% glucose 100 ml stat) and/or IM glucagon 1 mg.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q14, p.10,11$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,$mmqz$[{"url": "/uploads/content-images/emrcog0224-q016-fig1.png", "caption": "Figure 1"}, {"url": "/uploads/content-images/emrcog0224-q016-fig2.png", "caption": "Figure 2"}]$mmqz$::jsonb,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q017$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$What is the risk in a patient with corrected tetralogy of Fallot according to the modified WHO classification of maternal cardiovascular risk?$mmqz$,$mmqz$[{"label": "A", "text": "Class I"}, {"label": "B", "text": "Class II"}, {"label": "C", "text": "Class III"}, {"label": "D", "text": "Class IV"}, {"label": "E", "text": "Class V"}]$mmqz$::jsonb,$mmqz$Class II$mmqz$,$mmqz$According to the modified WHO classification of maternal cardiovascular risk, repaired tetralogy of Fallot is Class II (small increased risk of maternal mortality or moderate increase in morbidity). Class II also includes unoperated atrial or ventricular septal defect and most arrhythmias.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q15, p.11$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,$mmqz$[{"url": "/uploads/content-images/emrcog0224-q017-fig1.png", "caption": "Figure 1"}]$mmqz$::jsonb,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q018$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$What is the fluid deficit cut off to prevent fluid overload when using an isotonic solution in operative hysteroscopy?$mmqz$,$mmqz$[{"label": "A", "text": "2500 ml"}, {"label": "B", "text": "1000 ml"}, {"label": "C", "text": "1500 ml"}, {"label": "D", "text": "750 ml"}]$mmqz$::jsonb,$mmqz$2500 ml$mmqz$,$mmqz$Definition of fluid overload: a fluid deficit of more than 1000 ml should be used as the threshold when using hypotonic solutions in healthy women of reproductive age [C]; a fluid deficit of 2500 ml should be used as the threshold when using isotonic solutions in healthy women of reproductive age [GPP]. A maximum fluid deficit of 1000 ml (hypotonic) or 2500 ml (isotonic) should be set in a healthy woman and surgery stopped on reaching this limit. Lower thresholds apply in the elderly and women with cardiovascular, renal or other co-morbidities (suggested upper limits 750 ml hypotonic and 1500 ml isotonic).$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q16, p.12,13$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,$mmqz$[{"url": "/uploads/content-images/emrcog0224-q018-fig1.png", "caption": "Figure 1"}, {"url": "/uploads/content-images/emrcog0224-q018-fig2.png", "caption": "Figure 2"}]$mmqz$::jsonb,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q019$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$Patient is planned to undergo laparoscopic hysterectomy for benign disease. She is hypertensive and has a history of atrial fibrillation. She is on warfarin which was stopped 5 days before operation. What is the recommendation for bridging thromboprophylaxis for her?$mmqz$,$mmqz$[{"label": "A", "text": "No need for bridging therapy"}, {"label": "B", "text": "Bridge with prophylactic LMWH and stop 24 hours before operation"}, {"label": "C", "text": "Bridge with prophylactic LMWH and stop 48 hours before operation"}, {"label": "D", "text": "Bridge with therapeutic LMWH and stop 24 hours before operation"}, {"label": "E", "text": "Bridge with therapeutic LMWH and stop 48 hours before operation"}]$mmqz$::jsonb,$mmqz$Bridge with therapeutic LMWH and stop 24 hours before operation$mmqz$,$mmqz$All patients taking warfarin should stop treatment 5 days before surgery, irrespective of their risk of intraoperative bleeding. Bridge with therapeutic-dose LMWH, with the therapeutic dose stopped 24 hours before surgery; bridging with LMWH should be continued until the INR is in therapeutic range. Warfarin can be resumed at the normal maintenance dose the evening of surgery or the next day if haemostasis is adequate. For procedures with a high bleeding risk, the British Society of Haematology recommends that bridging (full-dose anticoagulation) should not be restarted until at least 48 hours after the procedure.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q17, p.13,14$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,$mmqz$[{"url": "/uploads/content-images/emrcog0224-q019-fig1.png", "caption": "Figure 1"}]$mmqz$::jsonb,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q020$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$What is the recommended imaging technique for levator ani muscle avulsion injury?$mmqz$,$mmqz$[{"label": "A", "text": "MRI"}, {"label": "B", "text": "Transperineal USG"}, {"label": "C", "text": "Transvaginal USG"}, {"label": "D", "text": "Endoanal USG"}, {"label": "E", "text": "Tomographic imaging"}]$mmqz$::jsonb,$mmqz$Tomographic imaging$mmqz$,$mmqz$Maternal birth trauma in the form of levator ani muscle (LAM) avulsion occurs in 10–36% of women during vaginal childbirth. Forceps is the primary modifiable risk factor (odds ratios 4–5 for avulsion relative to Ventouse); rotational forceps appear particularly traumatic. In equivocal cases, a levator–urethra gap of greater than 25 mm can clarify findings. Since diagnosis by palpation has poor agreement with both transperineal and endovaginal ultrasound, diagnosis using tomographic imaging is currently the gold standard. (Note: the correct option was not highlighted in the source document; it is inferred from the explanation.)$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q18, p.14,15$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,$mmqz$[{"url": "/uploads/content-images/emrcog0224-q020-fig1.png", "caption": "Figure 1"}]$mmqz$::jsonb,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q021$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$What is the recommended venous thromboprophylaxis for a 35 yr old patient who underwent elective CS? Her BMI was 24.$mmqz$,$mmqz$[{"label": "A", "text": "No need of thromboprophylaxis"}, {"label": "B", "text": "Consider thromboprophylaxis for at least 10 days"}, {"label": "C", "text": "At least 6 weeks' postnatal prophylactic LMWH"}, {"label": "D", "text": "Consider extending thromboprophylaxis with LMWH"}, {"label": "E", "text": "Early mobilisation and avoidance of dehydration"}]$mmqz$::jsonb,$mmqz$Early mobilisation and avoidance of dehydration$mmqz$,$mmqz$A woman undergoing elective caesarean section with no additional risk factors (age 35, BMI 24) does not require pharmacological thromboprophylaxis; early mobilisation and avoidance of dehydration are recommended.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q19, p.15$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,NULL,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q022$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$What is the venous thromboprophylaxis recommendation for a G3, 36 years old patient with heterozygous prothrombin gene mutation? Her weight is 98 kg.$mmqz$,$mmqz$[{"label": "A", "text": "5000u dalteparin twice daily"}, {"label": "B", "text": "2500u dalteparin once daily"}, {"label": "C", "text": "40 mg enoxaparin once daily"}, {"label": "D", "text": "60 mg enoxaparin twice daily"}, {"label": "E", "text": "7500u dalteparin once daily"}]$mmqz$::jsonb,$mmqz$7500u dalteparin once daily$mmqz$,$mmqz$Heterozygosity for factor V Leiden or prothrombin gene mutation or antiphospholipid antibodies are risk factors for thrombosis in asymptomatic women; parity ≥ 3 and age > 35 years are additional risk factors. Suggested thromboprophylactic LMWH dose by weight (Table 3): for 91–130 kg, dalteparin 7500 units daily (or enoxaparin 60 mg daily).$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q20, p.16$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,$mmqz$[{"url": "/uploads/content-images/emrcog0224-q022-fig1.png", "caption": "Figure 1"}]$mmqz$::jsonb,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q023$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$A long scenario describing a 65 kg patient requiring thromboprophylaxis. Options given were various doses of LMWH.$mmqz$,$mmqz$[{"label": "A", "text": "5000u dalteparin twice daily"}, {"label": "B", "text": "2500u dalteparin once daily"}, {"label": "C", "text": "40 mg enoxaparin once daily"}, {"label": "D", "text": "60 mg enoxaparin twice daily"}, {"label": "E", "text": "7500u dalteparin once daily"}]$mmqz$::jsonb,$mmqz$40 mg enoxaparin once daily$mmqz$,$mmqz$Thromboprophylactic LMWH dose is based on booking/early-pregnancy weight (Table 3). For a woman weighing 50–90 kg, the dose is enoxaparin 40 mg daily (or dalteparin 5000 units daily). VTE risk assessment (Appendix III): if total score ≥ 4 antenatally consider thromboprophylaxis from the first trimester; if score 3, from 28 weeks; if score ≥ 2 postnatally, for at least 10 days.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q21, p.17$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,$mmqz$[{"url": "/uploads/content-images/emrcog0224-q023-fig1.png", "caption": "Figure 1"}, {"url": "/uploads/content-images/emrcog0224-q023-fig2.png", "caption": "Figure 2"}]$mmqz$::jsonb,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q024$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$Antenatal patient presented with hyperemesis gravidarum. Her PUQE score was 10. She continued vomiting despite a combination of first line medications. What action is to be taken?$mmqz$,$mmqz$[{"label": "A", "text": "Ondansetron"}, {"label": "B", "text": "Ondansetron and domperidone"}, {"label": "C", "text": "Cyclizine and ondansetron"}, {"label": "D", "text": "Add Metoclopramide"}, {"label": "E", "text": "Prochlorperazine"}]$mmqz$::jsonb,$mmqz$Add Metoclopramide$mmqz$,$mmqz$Be careful: if one drug is used you can use a combination of up to 3 medications. When up-titrating antiemetics, add drugs from different classes rather than replacing them, as they may have synergistic effects; some women require a combination of 3+ antiemetics. First line: doxylamine/pyridoxine, cyclizine, prochlorperazine, promethazine, chlorpromazine. Second line: metoclopramide, domperidone, ondansetron. Third line: prednisolone. As the patient failed first-line combination, add a second-line agent (metoclopramide).$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q22, p.17,18$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,$mmqz$[{"url": "/uploads/content-images/emrcog0224-q024-fig1.png", "caption": "Figure 1"}]$mmqz$::jsonb,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q025$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$What is the recommended management of recurrent genital herpes in a woman at 20 weeks of gestation?$mmqz$,$mmqz$[{"label": "A", "text": "Daily suppressive dose from now"}, {"label": "B", "text": "Daily suppressive dose from 36 weeks"}, {"label": "C", "text": "Saline bath"}, {"label": "D", "text": "Analgesia"}]$mmqz$::jsonb,$mmqz$Daily suppressive dose from 36 weeks$mmqz$,$mmqz$Recurrences usually resolve within 7–10 days without antiviral treatment. Supportive treatment measures usually suffice (e.g. saline bathing, paracetamol). Vaginal delivery should be anticipated. Consider daily suppressive aciclovir 400 mg TDS from 36 weeks (increased dose compared with standard suppression in non-pregnant patients). Discuss risks, benefits and alternatives with women. Sequential PCR culture during late pregnancy or delivery is not indicated.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q23, p.18,19$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,NULL,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q026$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$Woman was on combined oral contraceptive pills. She missed the pill on day 10 and had UPSI after 16 hours. She visited the contraceptive clinic the next day. What is the further course recommended for her?$mmqz$,$mmqz$[{"label": "A", "text": "Reassure her, take the missed pill as soon as possible"}, {"label": "B", "text": "Consider EC, take the missed pill as soon as possible"}, {"label": "C", "text": "Consider EC, take the missed pill as soon as possible; condoms should be used or sex avoided until pills have been taken for 7 consecutive days"}, {"label": "D", "text": "Consider EC, take the missed pill as soon as possible; condoms should be used or sex avoided until pills have been taken for 7 consecutive days; UPT from 3 wks of last UPSI"}]$mmqz$::jsonb,$mmqz$Reassure her, take the missed pill as soon as possible$mmqz$,$mmqz$A COC pill is missed if it is not taken within 24 hours after it should have been taken. For 1 missed pill (48 to <72 hours since the last pill in the current pack was taken), whether in week 1, 2 or 3: take the missed pill as soon as possible, continue the remaining pills at the usual time, EC is not required and no additional contraceptive precaution is required (provided consistent, correct use previously). Reassure and advise to take the missed pill as soon as possible.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q24, p.19$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,$mmqz$[{"url": "/uploads/content-images/emrcog0224-q026-fig1.png", "caption": "Figure 1"}]$mmqz$::jsonb,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q027$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$Antenatal mother who is a school teacher presented with a lacy rash associated with fever. Which of the following is the most probable infection?$mmqz$,$mmqz$[{"label": "A", "text": "Parvovirus infection"}, {"label": "B", "text": "CMV"}, {"label": "C", "text": "Toxoplasmosis"}, {"label": "D", "text": "Measles"}, {"label": "E", "text": "Rubella"}]$mmqz$::jsonb,$mmqz$Parvovirus infection$mmqz$,$mmqz$Parvovirus B19 infection has a wide range of consequences, from minor febrile illness to erythema infectiosum (fifth disease, slapped cheek syndrome) — a generalised lacy rash illness clinically indistinguishable from rubella — aplastic crises, arthropathy, and persistent infection in the immunocompromised. Recent infection can be confirmed by parvovirus B19-specific IgM on the first serum from the day after rash onset. Management of proven infection includes specialist advice, serial ultrasound scanning and Doppler assessment (fetal anaemia/hydrops), with intrauterine transfusion improving outcome.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q25, p.19,20$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,NULL,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q028$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$A woman in her 60s was newly diagnosed with lichen sclerosus. What action is to be taken as part of further investigations?$mmqz$,$mmqz$[{"label": "A", "text": "Thyroid profile"}, {"label": "B", "text": "Fasting blood sugar"}, {"label": "C", "text": "OGTT"}, {"label": "D", "text": "Wedge biopsy"}]$mmqz$::jsonb,$mmqz$Thyroid profile$mmqz$,$mmqz$Investigation for autoimmune disease if clinically indicated, especially thyroid dysfunction (i.e. thyroid autoantibodies and TSH), as it can commonly be present together with lichen sclerosus.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q26, p.20$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,NULL,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q029$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$HPE of the LLETZ specimen measuring 3x3 cm showed an invasive carcinoma of the cervix with stromal invasion of 1 mm depth, and 6 mm of surrounding tissue showed CIN3. The specimen had a clear margin of >5 mm. What is the stage of cancer cervix?$mmqz$,$mmqz$[{"label": "A", "text": "Stage IA1"}, {"label": "B", "text": "Stage IA2"}, {"label": "C", "text": "Stage IB1"}, {"label": "D", "text": "Stage IB2"}]$mmqz$::jsonb,$mmqz$Stage IA1$mmqz$,$mmqz$FIGO staging of cervical cancer: Stage IA is invasive carcinoma diagnosed only by microscopy, with maximum depth of invasion ≤5 mm. IA1 = measured stromal invasion ≤3 mm in depth; IA2 = >3 and ≤5 mm. With 1 mm stromal invasion, this is Stage IA1.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q27, p.20,21$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,$mmqz$[{"url": "/uploads/content-images/emrcog0224-q029-fig1.png", "caption": "Figure 1"}]$mmqz$::jsonb,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q030$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$Staging laparotomy for cancer confined to the right ovary was done. The peritoneal washings show malignant cells. What is the stage of the tumour?$mmqz$,$mmqz$[{"label": "A", "text": "IA"}, {"label": "B", "text": "IIB"}, {"label": "C", "text": "IC1"}, {"label": "D", "text": "IC2"}, {"label": "E", "text": "IC3"}]$mmqz$::jsonb,$mmqz$IC3$mmqz$,$mmqz$FIGO staging of ovarian cancer, Stage I (tumour confined to ovaries/fallopian tubes): IA = limited to 1 ovary, capsule intact, no malignant cells in washings; IC = limited to 1 or both ovaries with any of: IC1 surgical spill, IC2 capsule ruptured before surgery or tumour on surface, IC3 malignant cells in the ascites or peritoneal washings. Malignant cells in peritoneal washings with tumour confined to one ovary = Stage IC3.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q28, p.21$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,$mmqz$[{"url": "/uploads/content-images/emrcog0224-q030-fig1.png", "caption": "Figure 1"}]$mmqz$::jsonb,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q031$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$Patient came to gyne clinic with a pigmented vulval lesion measuring 8 mm. What action would you take?$mmqz$,$mmqz$[{"label": "A", "text": "Incisional biopsy"}, {"label": "B", "text": "Excisional biopsy"}, {"label": "C", "text": "Punch biopsy"}]$mmqz$::jsonb,$mmqz$Incisional biopsy$mmqz$,$mmqz$Diagnosis: incisional biopsy (punch or wedge biopsy) ideally including the edge of a lesion, where there is a transition from normal to abnormal tissue. Biopsies should avoid a central ulcer, since this may not be diagnostic, and should be of adequate depth to allow differentiation between superficially invasive lesions and those with invasion >1 mm, since this informs subsequent management.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q29, p.21,22$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,$mmqz$[{"url": "/uploads/content-images/emrcog0224-q031-fig1.png", "caption": "Figure 1"}]$mmqz$::jsonb,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q032$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$What is the recommended management to prevent recurrence of Bartholin's abscess in a patient who was treated before?$mmqz$,$mmqz$[{"label": "A", "text": "Word catheter method"}, {"label": "B", "text": "Marsupialization"}, {"label": "C", "text": "Sclerotherapy"}, {"label": "D", "text": "Needle aspiration"}, {"label": "E", "text": "Jacobi ring catheter"}]$mmqz$::jsonb,$mmqz$Marsupialization$mmqz$,$mmqz$Marsupialization is recommended to prevent recurrence of Bartholin's abscess/cyst. Comparative recurrence rates: balloon Word catheter 12% at 12 months (23% premature expulsion, painful, latex allergy contraindication); Jacobi ring catheter 4% at 12 months (needs two incisions, painful); alcohol sclerotherapy 8–10% within 6–7 months (risk of necrosis, haematoma, dyspareunia); silver nitrate sclerotherapy 3.8% at 2 months (scarring, chemical burns); needle aspiration 13% recurrence (not recommended).$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q30, p.22$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,NULL,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q033$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$During a difficult gynaecology surgery a bladder injury was diagnosed intra-operatively and primary repair was done. Postoperative cystoscopy was done and an adequate repair was ascertained. Now the patient presented with urine leak through the vagina. How to investigate her?$mmqz$,$mmqz$[{"label": "A", "text": "Cystoscopy"}, {"label": "B", "text": "Cystogram"}, {"label": "C", "text": "MRI"}, {"label": "D", "text": "CT urogram"}, {"label": "E", "text": "Intravenous pyelogram"}]$mmqz$::jsonb,$mmqz$Cystoscopy$mmqz$,$mmqz$In late presentations where a fistula is suspected, diagnosis is supported by filling the bladder with dye (e.g. methylene blue) and demonstrating vaginal leakage; MRI provides good tissue contrast and can be diagnostic for a vesico-vaginal fistula. Bladder repairs should be watertight and tested (methylene blue or indigo carmine); a catheter is inserted with continuous drainage for 2 weeks. Before catheter removal, complete repair without leakage should be confirmed by retrograde cystography; if contrast escapes, leave the catheter and repeat in 1 week. Cystoscopic examination can assist in the decision.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q31, p.23$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,NULL,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q034$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$Following a laparoscopic gyne surgery for endometriosis, the patient presented with left-sided flank pain, haematuria and fever. What is the probable cause?$mmqz$,$mmqz$[{"label": "A", "text": "Ureteric injury"}, {"label": "B", "text": "Bladder injury"}, {"label": "C", "text": "Bowel injury"}, {"label": "D", "text": "Urinary tract infection"}]$mmqz$::jsonb,$mmqz$Ureteric injury$mmqz$,$mmqz$Any failure to recover as anticipated following major laparoscopic pelvic surgery must raise suspicion of a ureteric injury. Flank pain and tenderness, haematuria, oliguria or watery vaginal loss may be present within the first 48 hours of an acute injury (uroperitoneum).$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q32, p.23,24$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,NULL,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q035$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$Patient from Zambia had no antenatal care. The newborn is noticed to have nasal stuffiness, sabre shin, rashes on palms and soles and hepatosplenomegaly. What is the diagnosis?$mmqz$,$mmqz$[{"label": "A", "text": "Early congenital syphilis"}, {"label": "B", "text": "Late congenital syphilis"}, {"label": "C", "text": "Zika infection"}, {"label": "D", "text": "CMV"}, {"label": "E", "text": "Parvovirus"}, {"label": "F", "text": "Fetal varicella syndrome"}]$mmqz$::jsonb,$mmqz$Early congenital syphilis$mmqz$,$mmqz$Early congenital syphilis (within two years): approximately half of neonates are normal on initial examination. Common manifestations (40–60% have at least one) include rash, haemorrhagic rhinitis (bloody snuffles), generalised lymphadenopathy, hepatosplenomegaly and skeletal abnormalities. Other signs: condylomata lata, vesiculobullous lesions, osteochondritis, periostitis, pseudoparalysis, mucous patches, perioral fissures, non-immune hydrops, glomerulonephritis, neurological/ocular involvement, haemolysis, thrombocytopenia. Late congenital syphilis shows stigmata such as interstitial keratitis, Clutton's joints, Hutchinson's incisors, mulberry molars, saddlenose deformity and sabre shins.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q33, p.24,25$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,$mmqz$[{"url": "/uploads/content-images/emrcog0224-q035-fig1.png", "caption": "Figure 1"}, {"url": "/uploads/content-images/emrcog0224-q035-fig2.png", "caption": "Figure 2"}]$mmqz$::jsonb,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q036$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$What is the major cause of mortality in women with epilepsy during pregnancy?$mmqz$,$mmqz$[{"label": "A", "text": "SUDEP"}, {"label": "B", "text": "Usage of lamotrigine"}, {"label": "C", "text": "Drowning"}, {"label": "D", "text": "Status epilepticus"}, {"label": "E", "text": "Change of medications"}]$mmqz$::jsonb,$mmqz$SUDEP$mmqz$,$mmqz$SUDEP (sudden unexpected death in epilepsy): poorly controlled seizures is the main contributory factor. The higher risk in pregnancy is explained partly by the relatively common use of lamotrigine and reduced serum drug levels with advancing gestation, potentially increasing seizure frequency.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q34, p.25$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,NULL,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q037$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$A prepubescent girl presents with vulvovaginal discharge. Her smear shows gram-negative diplococci. What is the possible cause?$mmqz$,$mmqz$[{"label": "A", "text": "Group A beta-haemolytic streptococci"}, {"label": "B", "text": "Staphylococci"}, {"label": "C", "text": "Candida"}, {"label": "D", "text": "Neisseria"}, {"label": "E", "text": "Mixed bacterial flora"}]$mmqz$::jsonb,$mmqz$Neisseria$mmqz$,$mmqz$Gram-negative diplococci indicate Neisseria gonorrhoeae. Causes of childhood vulvovaginitis: most common is non-specific with mixed bacterial flora; infective causes include Group A beta-haemolytic streptococcus, Haemophilus influenzae, and Candida (unusual); systemic infections include varicella, measles, rubella, diphtheria, shigella; vulval dermatitis (soap, bubble bath, sandpit, urine/faeces contact, irritants) and foreign bodies are non-infective causes.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q35, p.25,26$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,$mmqz$[{"url": "/uploads/content-images/emrcog0224-q037-fig1.png", "caption": "Figure 1"}]$mmqz$::jsonb,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q038$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$A labouring woman was exhausted. During vacuum delivery, the cup popped off twice with good descent after each application. Vertex is now at +2. How to proceed further, since she has consented only for vacuum delivery?$mmqz$,$mmqz$[{"label": "A", "text": "Low vacuum application"}, {"label": "B", "text": "Midcavity in labour ward"}, {"label": "C", "text": "Instrumental delivery trial"}, {"label": "D", "text": "Cat 1 CS"}, {"label": "E", "text": "Cat 2 CS"}]$mmqz$::jsonb,$mmqz$Cat 1 CS$mmqz$,$mmqz$After 2 pop-offs of the vacuum, discontinue vacuum delivery. Although the station is low (+2) and forceps could technically be applied, the patient gave consent only for vacuum, so proceed to caesarean section. Discontinue vacuum-assisted birth if two 'pop-offs' of the instrument occur; consider the consequences of a failed attempt at operative vaginal birth (increased trauma/OASI with sequential instruments, increased maternal morbidity and fetal head impaction at caesarean in second stage).$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q36, p.26$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,$mmqz$[{"url": "/uploads/content-images/emrcog0224-q038-fig1.png", "caption": "Figure 1"}]$mmqz$::jsonb,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q039$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$An antenatal woman presented with retro-orbital headache on and off since her 20th week. Her BMI is 40. Examination showed no focal neurological deficit. Her headache increased with cough. Examination showed features suggestive of 6th nerve palsy. What is the best investigation to confirm the diagnosis?$mmqz$,$mmqz$[{"label": "A", "text": "Fundoscopy"}, {"label": "B", "text": "Lumbar puncture"}, {"label": "C", "text": "MR angiogram"}, {"label": "D", "text": "CT"}, {"label": "E", "text": "MRI brain"}]$mmqz$::jsonb,$mmqz$Lumbar puncture$mmqz$,$mmqz$Idiopathic intracranial hypertension (IIH) — Modified Dandy criteria: signs/symptoms of raised ICP (headache, nausea, vomiting, transient visual obscurations, papilloedema); no localising neurological signs except unilateral/bilateral sixth-nerve paresis; CSF shows increased pressure but no cytological/chemical abnormality; normal to small symmetric ventricles. The lumbar CSF opening pressure should be >250 mmH2O in the lateral decubitus position to diagnose IIH — CSF opening pressure is vital to confirm the diagnosis. Neuroimaging (CT adequate) is used to exclude other causes such as hydrocephalus.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q37, p.27$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,$mmqz$[{"url": "/uploads/content-images/emrcog0224-q039-fig1.png", "caption": "Figure 1"}]$mmqz$::jsonb,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q040$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$An antenatal patient came with a history of headache which started in week 20. Her BMI is 37. Examination showed no focal neurological symptoms. What is the probable cause?$mmqz$,$mmqz$[{"label": "A", "text": "Benign intracranial hypertension"}, {"label": "B", "text": "Migraine"}, {"label": "C", "text": "Tension headache"}, {"label": "D", "text": "SAH"}]$mmqz$::jsonb,$mmqz$Benign intracranial hypertension$mmqz$,$mmqz$There is not enough information in the question, but with a raised BMI and headache the probable cause is benign intracranial hypertension (idiopathic intracranial hypertension), especially if there is papilloedema and all imaging is normal. (Note: the correct option was not highlighted in the source; it is inferred from the accompanying note.)$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q38, p.27$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,NULL,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q041$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$Patient presented with acute RIF pain. An ultrasound showed a right-sided ovarian mass. Consent was obtained for laparoscopy + open and biopsy if needed. During laparoscopy, on visualising the peritoneal cavity, this was found to be a pedunculated tortuous hyperaemic fibroid approaching the right ovary. How to proceed with the management?$mmqz$,$mmqz$[{"label": "A", "text": "Do as consented"}, {"label": "B", "text": "Remove the fibroid"}, {"label": "C", "text": "Detorsion, abandon the procedure"}, {"label": "D", "text": "Remove the ovary"}, {"label": "E", "text": "Follow up in gyne clinic"}]$mmqz$::jsonb,$mmqz$Detorsion, abandon the procedure$mmqz$,$mmqz$Unexpected pathology: if unexpected disease is found at operation for which additional procedures are indicated, treatment may only be performed if the woman was made aware and consented to it beforehand; if such a preoperative discussion has not occurred, additional treatment should not take place. Where a complication that is itself life-threatening occurs, corrective surgery must proceed. Otherwise it is unwise to proceed with additional procedures without discussing with the woman. Here, detorse and abandon the procedure.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q39, p.27,28$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,$mmqz$[{"url": "/uploads/content-images/emrcog0224-q041-fig1.png", "caption": "Figure 1"}]$mmqz$::jsonb,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q042$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$A pregnant patient is brought to the ER with multiple trauma owing to a road traffic accident. How to investigate?$mmqz$,$mmqz$[{"label": "A", "text": "MRI"}, {"label": "B", "text": "Full body X-ray"}, {"label": "C", "text": "Full body CT"}, {"label": "D", "text": "MRI with IV contrast"}]$mmqz$::jsonb,$mmqz$Full body CT$mmqz$,NULL,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q40, p.28$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,NULL,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q043$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$A surgeon was doing an elective laparoscopic cholecystectomy. During surgery, a complex 10 cm ovarian mass was visualised on the left ovary. How to proceed in this situation?$mmqz$,$mmqz$[{"label": "A", "text": "Do as consented"}, {"label": "B", "text": "Abandon procedure"}, {"label": "C", "text": "Remove"}, {"label": "D", "text": "Seek another opinion"}, {"label": "E", "text": "Take a biopsy"}]$mmqz$::jsonb,$mmqz$Do as consented$mmqz$,$mmqz$Generally, it is unwise to proceed with any additional surgical procedures without discussing them with the woman, even if this means a second operation, unless clear boundaries about additional procedures were documented and consented before the procedure. Complete the operation as consented (cholecystectomy) and plan the ovarian mass separately.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q41, p.28$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,NULL,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q044$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$You are doing endometriosis surgery for a patient with severe adhesions. She consented for laparotomy if needed. During removal of the (x) ovary from (y) endometriosis, there was brisk bleeding and the patient gets worse. Ovarian artery injury was suspected.$mmqz$,$mmqz$[{"label": "A", "text": "Wait for your colleague"}, {"label": "B", "text": "Wait for second opinion"}, {"label": "C", "text": "Try to separate x from y"}, {"label": "D", "text": "Laparotomy and pan to remove y"}, {"label": "E", "text": "Removal of x to stop bleeding"}]$mmqz$::jsonb,$mmqz$Removal of x to stop bleeding$mmqz$,NULL,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q42, p.28$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,NULL,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q045$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$A patient who is a Jehovah's Witness is prepped for laparoscopic ovarian cystectomy. She signed an advance directive mentioning no blood transfusion. Following the surgery, the patient collapsed in the ward. Her examination showed signs of intra-abdominal collection. The patient is drowsy. How to proceed?$mmqz$,$mmqz$[{"label": "A", "text": "Perform a laparotomy in best-interest principle"}, {"label": "B", "text": "Adhere to advanced directive"}, {"label": "C", "text": "Need written consent from patient"}, {"label": "D", "text": "Patient consent is valid"}, {"label": "E", "text": "Verbal consent from patient"}, {"label": "F", "text": "Written consent from husband"}, {"label": "G", "text": "Wait for legal board for further treatment"}, {"label": "H", "text": "Patient consent is not valid"}]$mmqz$::jsonb,$mmqz$Perform a laparotomy in best-interest principle$mmqz$,$mmqz$Attempt to stop the bleeding and manage the acute intra-abdominal haemorrhage (laparotomy) under the best-interest principle, while respecting the valid advance directive refusing blood — so NO blood transfusion is given.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q43, p.29$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,NULL,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q046$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$A 15 year old girl and her 18 year old partner came for termination of an unwanted pregnancy. The girl lives with her father and occasionally visits her mother. She doesn't wish to tell her parents. How to proceed?$mmqz$,$mmqz$[{"label": "A", "text": "Proceed termination with the girl's consent if she is deemed to have capacity"}, {"label": "B", "text": "Encourage her to tell the parents"}, {"label": "C", "text": "Consent from partner"}, {"label": "D", "text": "Consent from parents"}, {"label": "E", "text": "Legal consent"}]$mmqz$::jsonb,$mmqz$Proceed termination with the girl's consent if she is deemed to have capacity$mmqz$,$mmqz$If the young person is deemed to have capacity (Gillick competent), proceed with termination using her own consent. Parental involvement should be encouraged but cannot be required if she is competent and refuses.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q44, p.29$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,NULL,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q047$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$What is the risk of offspring being affected when both parents are carriers of cystic fibrosis?$mmqz$,$mmqz$[{"label": "A", "text": "All the offspring"}, {"label": "B", "text": "½"}, {"label": "C", "text": "¼"}, {"label": "D", "text": "All are carriers"}]$mmqz$::jsonb,$mmqz$¼$mmqz$,$mmqz$Cystic fibrosis is autosomal recessive. When both parents are carriers (Cc × Cc), the Punnett square gives CC (1/4 unaffected), Cc and Cc (1/2 carriers) and cc (1/4 affected). Therefore the risk of an affected child is 1/4.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q45, p.29$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,NULL,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q048$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$A premenopausal patient comes to the gyne emergency with abdominal pain and USG revealed an ovarian cyst with mixed echogenicity measuring 8x7x8 cm. What is the best management?$mmqz$,$mmqz$[{"label": "A", "text": "Antibiotics"}, {"label": "B", "text": "Conservative management"}, {"label": "C", "text": "Lap cystectomy"}, {"label": "D", "text": "Laparotomy"}, {"label": "E", "text": "Ovarian cystectomy"}]$mmqz$::jsonb,$mmqz$Lap cystectomy$mmqz$,$mmqz$A persistent large (8 cm) complex/mixed-echogenicity ovarian cyst in a premenopausal woman presenting with pain is best managed by laparoscopic cystectomy.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q46, p.29$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,NULL,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q049$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$How many more women would need to undergo peripartum hysterectomy if caesarean section was done compared to a vaginal delivery?$mmqz$,$mmqz$[{"label": "A", "text": "65 more women / 100000"}, {"label": "B", "text": "200 more women / 100000"}, {"label": "C", "text": "24 more women / 100000"}, {"label": "D", "text": "80 more women / 100000"}, {"label": "E", "text": "150 more women / 100000"}]$mmqz$::jsonb,$mmqz$65 more women / 100000$mmqz$,$mmqz$RCOG consent data (Table 1, outcomes more likely with caesarean birth): about 65 more women per 100,000 who had a caesarean birth would be expected to have a peripartum hysterectomy (about 200 per 100,000 with caesarean vs about 100 per 100,000 with vaginal birth), so for about 99,935 women per 100,000 the outcome was the same irrespective of mode of birth.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q47, p.30,31$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,$mmqz$[{"url": "/uploads/content-images/emrcog0224-q049-fig1.png", "caption": "Figure 1"}, {"url": "/uploads/content-images/emrcog0224-q049-fig2.png", "caption": "Figure 2"}]$mmqz$::jsonb,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q050$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$Patient was on warfarin for AF. Her INR is maintained at 2.5. She is planned for polypectomy. Preoperatively, the INR is 1.6. How to proceed in this situation?$mmqz$,$mmqz$[{"label": "A", "text": "Give Phytomenadione"}, {"label": "B", "text": "Repeat INR and review"}, {"label": "C", "text": "Defer operation until proper bridging"}, {"label": "D", "text": "Proceed for surgery"}]$mmqz$::jsonb,$mmqz$Give Phytomenadione$mmqz$,$mmqz$Warfarin should be stopped 5 days before elective surgery with an INR check ideally the day before surgery: if the INR is >1.5 the day before surgery, phytomenadione (vitamin K) should be given. Here the INR is 1.6 (>1.5), so give phytomenadione. LMWH bridging is considered in those with high VTE risk. Restart warfarin when haemostasis is achieved (low bleeding risk ~12–24 h; high bleeding risk LMWH not until 48 h after surgery).$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q48, p.31$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,$mmqz$[{"url": "/uploads/content-images/emrcog0224-q050-fig1.png", "caption": "Figure 1"}]$mmqz$::jsonb,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q051$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$Antenatal haemoglobinopathy screening: the woman is of UK origin. Her partner's family of origin is not known. What is the appropriate action?$mmqz$,$mmqz$[{"label": "A", "text": "No further tests"}, {"label": "B", "text": "NIPT"}, {"label": "C", "text": "CVS/amnio"}, {"label": "D", "text": "Newborn screening"}, {"label": "E", "text": "Paternal screening"}, {"label": "F", "text": "Parental karyotyping"}, {"label": "G", "text": "Maternal screening"}]$mmqz$::jsonb,$mmqz$Maternal screening$mmqz$,$mmqz$When the father's origin is unknown (or from a high-prevalence area), this is considered high risk. Offer a blood test for the mother (maternal screening) to identify whether she is a carrier. Sickle cell screening: Family Origin Questionnaire → if high risk, HPLC → if carrier, test father → if both carriers, offer prenatal invasive testing (CVS/amniocentesis). Thalassaemia screening is offered to all pregnant women in the UK (MCH <27 pg → HPLC → test father → invasive testing if both carriers).$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q49, p.32$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,$mmqz$[{"url": "/uploads/content-images/emrcog0224-q051-fig1.png", "caption": "Figure 1"}]$mmqz$::jsonb,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q052$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$Parents are carriers for CAH (congenital adrenal hyperplasia). What is the risk of offspring inheriting the disease?$mmqz$,$mmqz$[{"label": "A", "text": "1 in 2"}, {"label": "B", "text": "1 in 4"}, {"label": "C", "text": "3 in 4"}, {"label": "D", "text": "No risk of offspring inheriting the disease"}]$mmqz$::jsonb,$mmqz$1 in 4$mmqz$,$mmqz$CAH is autosomal recessive. When both parents are carriers (Aa × Aa), the Punnett square gives AA (1/4 unaffected), Aa and Aa (1/2 carriers) and aa (1/4 affected). The risk of an affected child is 1 in 4.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q50, p.33$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,NULL,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q053$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$Woman presented with features of overactive bladder. Her urodynamic findings confirmed her symptoms. Which of the following is representative of detrusor overactivity (DO)?$mmqz$,$mmqz$[{"label": "A", "text": "Evidence of leak with provocation, with no rise in Pdet"}, {"label": "B", "text": "Provoked or unprovoked rise in detrusor pressure that is abnormal and correlates with leak: positive flow during filling / Pabd stable / Pdet increase 2–27 / leakage +/− / normal flow"}, {"label": "C", "text": "Rise in detrusor pressure during filling, but the pressure falls to normal when filling is stopped"}]$mmqz$::jsonb,$mmqz$Provoked or unprovoked rise in detrusor pressure that is abnormal and correlates with leak: positive flow during filling / Pabd stable / Pdet increase 2–27 / leakage +/− / normal flow$mmqz$,$mmqz$Detrusor overactivity (DO) is characterised by involuntary detrusor contractions during the filling phase (spontaneous or provoked, amplitudes >15 cm H2O) that are abnormal and correlate with leak. Phasic DO = waves of contraction that may or may not be associated with incontinence; terminal DO = a single involuntary contraction at cystometric capacity; cough-associated DO = onset immediately following a cough pressure peak. (Option c describes poor detrusor accommodation; option a describes urodynamic stress incontinence.)$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q51, p.33,34$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,$mmqz$[{"url": "/uploads/content-images/emrcog0224-q053-fig1.png", "caption": "Figure 1"}]$mmqz$::jsonb,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q054$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$Patient underwent mid-urethral tape in the past for SUI. Following her surgery she was symptom free for some time, and now presents again with SUI. No residual urine on investigations. What is the next step in her management?$mmqz$,$mmqz$[{"label": "A", "text": "Urodynamics"}, {"label": "B", "text": "Colposuspension"}, {"label": "C", "text": "TVT again"}, {"label": "D", "text": "Bulking agents"}, {"label": "E", "text": "Cystoscopy"}]$mmqz$::jsonb,$mmqz$Urodynamics$mmqz$,$mmqz$For recurrent stress urinary incontinence after a previous continence procedure, the best investigation is urodynamics; subsequent management is often with urethral bulking agents.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q52, p.34$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,NULL,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q055$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$A pregnant woman at 7 weeks amenorrhoea came with complaint of spotting. USG shows a thickened endometrium with no intrauterine/extrauterine gestational sac (pregnancy of unknown location). On hCG follow up, the rise was 360 iu from 340 iu in 48 hours. How to proceed now?$mmqz$,$mmqz$[{"label": "A", "text": "hCG after 1 week"}, {"label": "B", "text": "US after 2 weeks"}, {"label": "C", "text": "TVS after 1 week"}, {"label": "D", "text": "TVS after 2 weeks"}, {"label": "E", "text": "Urgent review in early pregnancy unit within 24 hr"}]$mmqz$::jsonb,$mmqz$Urgent review in early pregnancy unit within 24 hr$mmqz$,$mmqz$For a woman with a pregnancy of unknown location and a decrease in serum hCG of less than 50%, or an increase of less than 63% over 48 hours, refer her for clinical review in the early pregnancy assessment service within 24 hours. A rise from 340 to 360 iu is a sub-optimal rise (<63%), so urgent EPU review within 24 hours is required (risk of ectopic).$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q53, p.34,35$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,$mmqz$[{"url": "/uploads/content-images/emrcog0224-q055-fig1.png", "caption": "Figure 1"}, {"url": "/uploads/content-images/emrcog0224-q055-fig2.png", "caption": "Figure 2"}]$mmqz$::jsonb,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q056$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$What is the initial management in a patient with a large cystocele and complaint of SUI?$mmqz$,$mmqz$[{"label": "A", "text": "PMFT (pelvic floor muscle training)"}, {"label": "B", "text": "Urodynamic test"}, {"label": "C", "text": "Pessary"}]$mmqz$::jsonb,$mmqz$PMFT (pelvic floor muscle training)$mmqz$,$mmqz$Initial (first-line) management is pelvic floor muscle training (PMFT).$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q54, p.35$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,NULL,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q057$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$What is the management of a persistent simple ovarian cyst in a postmenopausal woman? Her RMI is <200 and CA125 is normal.$mmqz$,$mmqz$[{"label": "A", "text": "Bilateral salpingo-oophorectomy"}, {"label": "B", "text": "Laparoscopic BSO"}, {"label": "C", "text": "TAH with BSO"}, {"label": "D", "text": "Discharge from follow up"}, {"label": "E", "text": "Repeat assessment in four months"}]$mmqz$::jsonb,$mmqz$Repeat assessment in four months$mmqz$,$mmqz$Asymptomatic, simple, unilateral, unilocular ovarian cysts less than 5 cm in diameter have a low risk of malignancy. With normal serum CA125 (RMI <200), they can be managed conservatively with a repeat evaluation in 4–6 months (CA125, TVS ± TAS). It is reasonable to discharge after 1 year if the cyst remains unchanged or reduces in size with normal CA125, considering the woman's wishes and surgical fitness.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q55, p.35,36$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,$mmqz$[{"url": "/uploads/content-images/emrcog0224-q057-fig1.png", "caption": "Figure 1"}]$mmqz$::jsonb,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q058$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$A postmenopausal woman was referred for a 4.5 cm simple ovarian cyst on CT scan, found during investigation for a surgical cause. CA125 is 17. What is the most appropriate management?$mmqz$,$mmqz$[{"label": "A", "text": "Laparotomy"}, {"label": "B", "text": "No further management"}, {"label": "C", "text": "Ultrasound and CA125 after 4 months"}, {"label": "D", "text": "Ultrasound and CA125 after 12 months"}, {"label": "E", "text": "Ultrasound after 4-6 months"}, {"label": "F", "text": "Bilateral salpingo-oophorectomy"}]$mmqz$::jsonb,$mmqz$Ultrasound and CA125 after 4 months$mmqz$,$mmqz$Asymptomatic, simple, unilateral, unilocular ovarian cysts <5 cm with normal CA125 have a low risk of malignancy in postmenopausal women and can be managed conservatively with repeat assessment (ultrasound and CA125) in 4–6 months. Discharge after 1 year if unchanged/reduced with normal CA125.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q56, p.36,37$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,$mmqz$[{"url": "/uploads/content-images/emrcog0224-q058-fig1.png", "caption": "Figure 1"}]$mmqz$::jsonb,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q059$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$What is the management of a simple ovarian cyst in a 23-year-old woman? The cyst measures 4.5 cm and is an incidental finding. She has no complaints so far.$mmqz$,$mmqz$[{"label": "A", "text": "Laparotomy"}, {"label": "B", "text": "Reassure, no further management"}, {"label": "C", "text": "Ultrasound and CA125 after 4 months"}, {"label": "D", "text": "Ultrasound and CA125 after 12 months"}, {"label": "E", "text": "Bilateral salpingo-oophorectomy"}, {"label": "F", "text": "Yearly assessment"}]$mmqz$::jsonb,$mmqz$Reassure, no further management$mmqz$,$mmqz$Women with small (less than 50 mm diameter) simple ovarian cysts generally do not require follow-up, as these cysts are very likely to be physiological and almost always resolve within 3 menstrual cycles. Cysts of 50–70 mm should have yearly ultrasound follow-up; larger simple cysts should be considered for further imaging (MRI) or surgical intervention.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q57, p.37$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,$mmqz$[{"url": "/uploads/content-images/emrcog0224-q059-fig1.png", "caption": "Figure 1"}]$mmqz$::jsonb,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q060$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$Patient presents with a history of reduced fetal movements. Her CTG shows a baseline of 140 bpm, normal variability, showing repetitive variable decelerations with concerning characteristics. Categorize the CTG.$mmqz$,$mmqz$[{"label": "A", "text": "Normal"}, {"label": "B", "text": "Pathological"}, {"label": "C", "text": "Suspicious"}, {"label": "D", "text": "Reassuring"}, {"label": "E", "text": "Non-reassuring"}]$mmqz$::jsonb,$mmqz$Pathological$mmqz$,$mmqz$Repetitive variable decelerations with concerning characteristics represent a pathological feature; a CTG with a pathological feature is classified as pathological.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q58, p.37,38$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,NULL,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q061$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$Patient presented with spontaneous rupture of membranes and regular contractions at term. Her examination revealed 4 cm cervical dilatation. 4 hours later, vaginal examination showed 5 cm cervical dilatation. Her CTG is normal. How to manage?$mmqz$,$mmqz$[{"label": "A", "text": "Reassess in 2 hours"}, {"label": "B", "text": "Reassess in 4 hrs"}, {"label": "C", "text": "Start oxytocin"}, {"label": "D", "text": "Perform cat 2 CS"}, {"label": "E", "text": "Perform cat 1 CS"}]$mmqz$::jsonb,$mmqz$Reassess in 2 hours$mmqz$,$mmqz$Advise all women with suspected delay in the established first stage of labour to have a vaginal examination 2 hours later, and diagnose delay if progress is less than 1 cm. Here progress was 1 cm over 4 hours, so reassess in 2 hours.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q59, p.37,38$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,NULL,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q062$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$Patient presents in labour at term gestation. She has been diagnosed with cardiac disease in the past — valvular heart disease with functional classification NYHA class 2. How to manage her?$mmqz$,$mmqz$[{"label": "A", "text": "Allow normal vaginal delivery"}, {"label": "B", "text": "Cut short second stage by vacuum delivery"}, {"label": "C", "text": "Cut short second stage by forceps delivery"}, {"label": "D", "text": "CS under GA"}, {"label": "E", "text": "CS under spinal"}, {"label": "F", "text": "CS under epidural"}]$mmqz$::jsonb,$mmqz$Allow normal vaginal delivery$mmqz$,$mmqz$Most women with well-compensated valvular heart disease (NYHA class 1–2) can be allowed a normal vaginal delivery; caesarean section is reserved for obstetric indications.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q60, p.38$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,NULL,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q063$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$Epileptic patient on topiramate came for contraceptive advice. What is the best option for her?$mmqz$,$mmqz$[{"label": "A", "text": "DMPA"}, {"label": "B", "text": "Implant"}, {"label": "C", "text": "Progesterone-only pills"}, {"label": "D", "text": "Barrier method"}]$mmqz$::jsonb,$mmqz$DMPA$mmqz$,$mmqz$Topiramate has enzyme-inducing activity at higher doses; as it is also a teratogen and there is wide inter-individual variability, FSRH advises treating topiramate as a potential enzyme inducer regardless of dose. Recommended contraceptive options are Cu-IUD, LNG-IUS or DMPA (plus condoms). Among the options given, DMPA is the best choice.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q61, p.38$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,$mmqz$[{"url": "/uploads/content-images/emrcog0224-q063-fig1.png", "caption": "Figure 1"}]$mmqz$::jsonb,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q064$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$What is the contraceptive option with the least failure rate?$mmqz$,$mmqz$[{"label": "A", "text": "Tubal ligation"}, {"label": "B", "text": "Vasectomy"}, {"label": "C", "text": "Implant"}, {"label": "D", "text": "DMPA"}, {"label": "E", "text": "LNG IUS"}]$mmqz$::jsonb,$mmqz$Implant$mmqz$,$mmqz$The progestogen-only implant has the lowest failure rate of the listed methods, at approximately 0.05% with both typical and perfect use.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q62, p.38,39$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,$mmqz$[{"url": "/uploads/content-images/emrcog0224-q064-fig1.png", "caption": "Figure 1"}]$mmqz$::jsonb,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q065$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$Woman who was on the combined contraceptive ring came with a history of the ring missing for the past 48 hours in the second week following the hormone-free interval. She has a history of UPSI 1 day back. How to counsel her?$mmqz$,$mmqz$[{"label": "A", "text": "EC is not required"}, {"label": "B", "text": "Consider EC"}, {"label": "C", "text": "Consider EC if correct use in the past 1 week"}, {"label": "D", "text": "Skip HFI, no need of EC"}, {"label": "E", "text": "EC is not required, insert ring ASAP, avoid intercourse for 7 days"}]$mmqz$::jsonb,$mmqz$EC is not required, insert ring ASAP, avoid intercourse for 7 days$mmqz$,$mmqz$For unscheduled ring removal of ≥48 hours in week 2 or 3 after the HFI, if there was correct consistent use in the previous 7 days, emergency contraception is not required. Insert the ring as soon as possible, keep it in until the scheduled removal day, and use condoms or avoid sex until the new ring has been used for 7 consecutive days.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q63, p.39,40$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,$mmqz$[{"url": "/uploads/content-images/emrcog0224-q065-fig1.png", "caption": "Figure 1"}, {"url": "/uploads/content-images/emrcog0224-q065-fig2.png", "caption": "Figure 2"}, {"url": "/uploads/content-images/emrcog0224-q065-fig3.png", "caption": "Figure 3"}]$mmqz$::jsonb,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q066$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$Epileptic patient on carbamazepine needs emergency contraception. She has a past history of PID. What to offer her?$mmqz$,$mmqz$[{"label": "A", "text": "Copper T"}, {"label": "B", "text": "LNG EC"}, {"label": "C", "text": "UPA EC"}, {"label": "D", "text": "Double dose LNG EC"}, {"label": "E", "text": "Double dose UPA EC"}]$mmqz$::jsonb,$mmqz$Copper T$mmqz$,$mmqz$Carbamazepine is an enzyme inducer that reduces the effectiveness of oral emergency contraception, so the copper IUD (Copper T) is the most effective option. Past PID (with no current STI risk factor) is UKMEC category 1 for the Cu-IUD, so it is not contraindicated.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q64, p.40,41$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,$mmqz$[{"url": "/uploads/content-images/emrcog0224-q066-fig1.png", "caption": "Figure 1"}]$mmqz$::jsonb,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q067$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$Patient presents with loin pain and haematuria on the 13th postoperative day following TAH. Her urine output was normal.$mmqz$,$mmqz$[{"label": "A", "text": "Ureteric injury"}, {"label": "B", "text": "Bladder injury"}, {"label": "C", "text": "Urinary tract infection"}]$mmqz$::jsonb,$mmqz$Ureteric injury$mmqz$,$mmqz$Delayed loin pain and haematuria after hysterectomy with preserved urine output suggests a ureteric injury.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q65, p.41$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,NULL,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q068$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$Following a laparoscopic surgery, a superficial burn was noticed on the patient's thigh. The surgical instrument included a hybrid cannula. What is the possible cause?$mmqz$,$mmqz$[{"label": "A", "text": "Direct injury"}, {"label": "B", "text": "Insulation failure"}, {"label": "C", "text": "Capacitative coupling"}]$mmqz$::jsonb,$mmqz$Capacitative coupling$mmqz$,$mmqz$With a hybrid cannula (mixed metal and plastic), even with intact insulation, if an open circuit is formed capacitive coupling increases and a trocar-site burn can occur. Other electrosurgical injuries include direct application (lateral thermal spread — the commonest), antenna coupling (a form of capacitive coupling), and direct coupling (active electrode touching another metal instrument).$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q66, p.41,42$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,NULL,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q069$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$Patient presents with paraesthesia and pain in the anterior and posterolateral thigh following TAH. Select the nerve involved.$mmqz$,$mmqz$[{"label": "A", "text": "Obturator nerve"}, {"label": "B", "text": "Femoral nerve"}, {"label": "C", "text": "Sciatic nerve"}, {"label": "D", "text": "Lateral cutaneous nerve of the thigh"}, {"label": "E", "text": "Iliohypogastric nerve"}]$mmqz$::jsonb,$mmqz$Lateral cutaneous nerve of the thigh$mmqz$,$mmqz$The lateral cutaneous nerve of the thigh (L2–L3) emerges from the lateral border of psoas, crosses the iliac fossa anterior to iliacus and enters the thigh posterior to the lateral end of the inguinal ligament. Injury during pelvic surgery causes paraesthesia and pain in the anterior and posterolateral thigh (meralgia paraesthetica).$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q67, p.42$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,$mmqz$[{"url": "/uploads/content-images/emrcog0224-q069-fig1.png", "caption": "Figure 1"}]$mmqz$::jsonb,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q070$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$Patient presents with foot drop and inability to dorsiflex her foot following TAH. Name the nerve involved.$mmqz$,$mmqz$[{"label": "A", "text": "Sciatic"}, {"label": "B", "text": "Common peroneal"}, {"label": "C", "text": "Tibial"}, {"label": "D", "text": "Lateral cutaneous nerve"}, {"label": "E", "text": "Genitofemoral"}]$mmqz$::jsonb,$mmqz$Common peroneal$mmqz$,$mmqz$Foot drop with inability to dorsiflex the foot indicates a common peroneal (fibular) nerve injury.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q68, p.42$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,$mmqz$[{"url": "/uploads/content-images/emrcog0224-q070-fig1.png", "caption": "Figure 1"}]$mmqz$::jsonb,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q071$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$Patient came back to the UK following oocyte retrieval. 25 oocytes were retrieved. The next morning, she wakes with severe right-sided abdominal pain associated with nausea and vomiting. She also complains of lightheadedness. What is the probable cause?$mmqz$,$mmqz$[{"label": "A", "text": "OHSS"}, {"label": "B", "text": "Ovarian torsion"}, {"label": "C", "text": "Ovarian rupture"}, {"label": "D", "text": "Appendicitis"}, {"label": "E", "text": "PID"}]$mmqz$::jsonb,$mmqz$OHSS$mmqz$,$mmqz$A high oocyte yield (25 retrieved) is a major risk factor for ovarian hyperstimulation syndrome (OHSS). Severe abdominal pain, nausea, vomiting and lightheadedness (from fluid shifts/hypovolaemia) shortly after retrieval indicate OHSS.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q69, p.43$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,NULL,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q072$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$According to the latest MBRRACE, what is the most common cause of direct maternal death?$mmqz$,$mmqz$[{"label": "A", "text": "Suicide"}, {"label": "B", "text": "VTE"}, {"label": "C", "text": "Cardiac cause"}, {"label": "D", "text": "Preeclampsia"}, {"label": "E", "text": "Bleeding"}]$mmqz$::jsonb,$mmqz$VTE$mmqz$,$mmqz$Thrombosis and thromboembolism (blood clots, ~16% of deaths) remains the leading cause of direct maternal death during or up to six weeks after the end of pregnancy. (Maternal suicide is the leading cause of direct death between 6 weeks and a year postpartum, and mental-health causes account for nearly 40% of deaths in that later period.)$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q70, p.43,44$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,$mmqz$[{"url": "/uploads/content-images/emrcog0224-q072-fig1.png", "caption": "Figure 1"}]$mmqz$::jsonb,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q073$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$A couple was evaluated for subfertility. The male partner's evaluation showed azoospermia and low FSH. What is the possible cause?$mmqz$,$mmqz$[{"label": "A", "text": "Kallmann syndrome"}, {"label": "B", "text": "Anabolic steroid"}, {"label": "C", "text": "Klinefelter syndrome"}, {"label": "D", "text": "CBAVD"}]$mmqz$::jsonb,$mmqz$Kallmann syndrome$mmqz$,$mmqz$Azoospermia with a LOW FSH indicates secondary (hypogonadotropic) hypogonadism. Kallmann syndrome is a congenital isolated gonadotropin (GnRH) deficiency causing low FSH/LH and impaired spermatogenesis. (Klinefelter and anabolic steroid abuse cause different hormonal pictures; CBAVD causes obstructive azoospermia with normal FSH.)$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q71, p.44,45$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,$mmqz$[{"url": "/uploads/content-images/emrcog0224-q073-fig1.png", "caption": "Figure 1"}]$mmqz$::jsonb,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q074$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$Couple was evaluated for infertility and planned for IVF. Male partner evaluation showed a severe deficit in sperm quantity: 4–5 million sperm per millilitre. Female partner evaluation was normal. What is the best option recommended for the couple?$mmqz$,$mmqz$[{"label": "A", "text": "IUI with partner sperm"}, {"label": "B", "text": "IUI with donor sperm"}, {"label": "C", "text": "IVF"}, {"label": "D", "text": "IVF-ICSI"}, {"label": "E", "text": "IVF with donor sperm"}]$mmqz$::jsonb,$mmqz$IVF-ICSI$mmqz$,$mmqz$The recognised indications for ICSI include severe deficits in semen quality and obstructive or non-obstructive azoospermia. With severe oligospermia, IVF with ICSI is recommended. Before ICSI, appropriate investigations and consideration of relevant genetic issues should be undertaken.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q72, p.45,46$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,NULL,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q075$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$What is the antihypertensive of choice in a postnatal patient? She is a known asthmatic with no history of recent exacerbations. She had stopped nifedipine due to drug allergy.$mmqz$,$mmqz$[{"label": "A", "text": "Enalapril"}, {"label": "B", "text": "Thiazide"}, {"label": "C", "text": "Amlodipine"}]$mmqz$::jsonb,$mmqz$Enalapril$mmqz$,$mmqz$Enalapril (an ACE inhibitor) is a suitable postnatal antihypertensive and is compatible with breastfeeding. Bronchospasm with enalapril is uncommon (≥1/1,000 to <1/100); cough is common. Contraindications include the 2nd and 3rd trimesters of pregnancy, hypersensitivity/angioedema with ACE inhibitors, and co-administration with aliskiren in diabetes or renal impairment (GFR <60).$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q73, p.46$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,NULL,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q076$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$Scenario describing bladder pain syndrome impacting on the patient's quality of life. What is the first-line management of bladder pain syndrome?$mmqz$,$mmqz$[{"label": "A", "text": "Amitriptyline"}, {"label": "B", "text": "Analgesics"}, {"label": "C", "text": "Cimetidine"}, {"label": "D", "text": "Oral cyclosporin"}, {"label": "E", "text": "Botox"}]$mmqz$::jsonb,$mmqz$Amitriptyline$mmqz$,$mmqz$Oral amitriptyline (or cimetidine) may be considered when first-line conservative treatments have failed; amitriptyline is the first-line oral pharmacological option for bladder pain syndrome.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q74, p.46$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,NULL,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q077$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$Genital examination of a patient showed the presence of genital piercing. Identify the type of FGM.$mmqz$,$mmqz$[{"label": "A", "text": "FGM Type 1"}, {"label": "B", "text": "FGM Type 2"}, {"label": "C", "text": "FGM Type 3"}, {"label": "D", "text": "FGM Type 4"}, {"label": "E", "text": "Not an FGM"}]$mmqz$::jsonb,$mmqz$FGM Type 4$mmqz$,$mmqz$WHO classification of FGM — Type 1: partial/total removal of the clitoris and/or prepuce (clitoridectomy). Type 2: removal of the clitoris and labia minora ± labia majora (excision). Type 3: narrowing of the vaginal orifice with a covering seal (infibulation). Type 4: all other harmful procedures for non-medical purposes, e.g. pricking, piercing, incising, scraping and cauterization. Genital piercing is Type 4.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q75, p.47$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,NULL,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q078$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$An antenatal woman with Anti-K (Kell) antibodies was on follow up. Her evaluation showed no fetal anaemia, MCA PSV normal, no hydrops, delivered vaginally at term. She should be counselled that the newborn baby is at risk of:$mmqz$,$mmqz$[{"label": "A", "text": "Early anaemia"}, {"label": "B", "text": "Early jaundice within 24 hours of delivery"}, {"label": "C", "text": "Late anaemia"}, {"label": "D", "text": "Late jaundice"}]$mmqz$::jsonb,$mmqz$Early anaemia$mmqz$,$mmqz$Kell (anti-K) antibodies suppress fetal/neonatal erythropoiesis rather than causing marked haemolysis, so the newborn is at risk of early neonatal anaemia (with relatively little jaundice).$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q76, p.47$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,NULL,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q079$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$You are teaching the midwife about normal labour and episiotomy. She wanted to know the maximum dose of 1% lignocaine without vasopressor for episiotomy for a woman weighing 80 kg.$mmqz$,$mmqz$[{"label": "A", "text": "1 mg/kg"}, {"label": "B", "text": "2 mg/kg"}, {"label": "C", "text": "3 mg/kg"}, {"label": "D", "text": "5 mg/kg"}, {"label": "E", "text": "7 mg/kg"}]$mmqz$::jsonb,$mmqz$3 mg/kg$mmqz$,$mmqz$Maximum dose of lidocaine (lignocaine) without adrenaline is 3 mg/kg (6 mg/kg with adrenaline). 1% = 10 mg/ml. For an 80 kg woman this is a maximum of 240 mg (24 ml of 1%).$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q77, p.47,48$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,$mmqz$[{"url": "/uploads/content-images/emrcog0224-q079-fig1.png", "caption": "Figure 1"}]$mmqz$::jsonb,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q080$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$What is the most common vessel injured in primary port insertion during laparoscopy?$mmqz$,$mmqz$[{"label": "A", "text": "Inferior epigastric artery"}, {"label": "B", "text": "Right common iliac artery"}, {"label": "C", "text": "Left common iliac artery"}, {"label": "D", "text": "Aorta"}, {"label": "E", "text": "Superficial epigastric artery"}]$mmqz$::jsonb,$mmqz$Aorta$mmqz$,$mmqz$With midline (umbilical) primary port entry, the major retroperitoneal vessels — the aorta and iliac vessels — are at risk. As the aortic bifurcation occurs just to the left of the midline, the right common iliac artery is at higher risk than the left during instrumentation at the umbilicus; keeping the Veress needle and trocar in the midline minimises this risk.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q78, p.48$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,$mmqz$[{"url": "/uploads/content-images/emrcog0224-q080-fig1.png", "caption": "Figure 1"}]$mmqz$::jsonb,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q081$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$What is the most common vessel injured in port insertion during laparoscopy (secondary/accessory ports)?$mmqz$,$mmqz$[{"label": "A", "text": "Inferior epigastric artery"}, {"label": "B", "text": "Right common iliac artery"}, {"label": "C", "text": "Left common iliac artery"}, {"label": "D", "text": "Aorta"}, {"label": "E", "text": "Superficial epigastric artery"}]$mmqz$::jsonb,$mmqz$Inferior epigastric artery$mmqz$,$mmqz$The most common trocar-induced abdominal wall injury is haemorrhage of the epigastric (inferior epigastric) vessels — a serious and potentially preventable complication of accessory port insertion.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q79, p.48$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,NULL,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q082$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$What is the most common injury in gynaecological laparoscopy?$mmqz$,$mmqz$[{"label": "A", "text": "Bladder"}, {"label": "B", "text": "Bowel"}, {"label": "C", "text": "Blood vessels"}, {"label": "D", "text": "Ureter"}]$mmqz$::jsonb,$mmqz$Bladder$mmqz$,$mmqz$Urinary tract injuries pooled together are the most common major complication of laparoscopic pelvic surgery, with bladder injury at the top of the list of visceral damage (reported rates 0.02%–8.3%). The overall rate of major complications is about 1.4/1000 procedures (intestinal 0.6/1000, urological 0.3/1000, vascular 0.1/1000).$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q80, p.48,49$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,NULL,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q083$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$What is the risk of bladder injury in diagnostic laparoscopy planned for chronic pelvic pain?$mmqz$,$mmqz$[{"label": "A", "text": "1 in 100"}, {"label": "B", "text": "2 in 1000"}, {"label": "C", "text": "3-8 / 10000"}, {"label": "D", "text": "14 in 100"}, {"label": "E", "text": "4 in 100"}]$mmqz$::jsonb,$mmqz$2 in 1000$mmqz$,$mmqz$The overall risk of serious complications from diagnostic laparoscopy is approximately 2 in 1000 women (uncommon). This includes damage to the bowel, bladder, ureters, uterus or major blood vessels that would require immediate repair by laparoscopy or laparotomy.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q81, p.49$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,$mmqz$[{"url": "/uploads/content-images/emrcog0224-q083-fig1.png", "caption": "Figure 1"}]$mmqz$::jsonb,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q084$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$What is the management of a patient presenting with PPROM at 29 weeks? Her examination showed normal fetal heart sounds and an uneffaced cervix.$mmqz$,$mmqz$[{"label": "A", "text": "MgSO4"}, {"label": "B", "text": "IV antibiotic + steroids"}, {"label": "C", "text": "Steroid + erythromycin"}, {"label": "D", "text": "Steroid + IOL with prostaglandin"}]$mmqz$::jsonb,$mmqz$Steroid + erythromycin$mmqz$,$mmqz$For preterm prelabour rupture of membranes (PPROM) without labour, give antenatal corticosteroids (for fetal lung maturity) plus oral erythromycin 250 mg four times a day for 10 days or until the woman is in established labour (whichever is sooner). Expectant management is appropriate at 29 weeks with a reassuring fetus and closed cervix.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q82, p.49$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,NULL,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q085$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$What is the most probable cause of virilization in a 42-year-old woman presenting with baldness and progressive hirsutism over the past 6 months? Her evaluation showed a testosterone of 7-8 and a normal DHEAS.$mmqz$,$mmqz$[{"label": "A", "text": "Sertoli-Leydig cell tumour"}, {"label": "B", "text": "Hyperthecosis"}, {"label": "C", "text": "Adrenal tumour"}, {"label": "D", "text": "PCOS"}, {"label": "E", "text": "Non-classical CAH"}]$mmqz$::jsonb,$mmqz$Sertoli-Leydig cell tumour$mmqz$,$mmqz$Rapid-onset virilization with a markedly raised testosterone but NORMAL DHEAS points to an ovarian (androgen-secreting) source rather than an adrenal one. A Sertoli-Leydig cell tumour is a testosterone-secreting ovarian tumour causing defeminization and progressive masculinization (amenorrhoea, deepening voice, hirsutism, male-pattern hair growth, clitoromegaly). Adrenal adenomas tend to secrete DHEA-S.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q83, p.49,50$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,NULL,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q086$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$How will you diagnose a case of hyperandrogenism in a teenage girl presenting with hirsutism and acne? She has not attained menarche. Her evaluation showed testosterone: 9.$mmqz$,$mmqz$[{"label": "A", "text": "17-hydroxyprogesterone"}, {"label": "B", "text": "DHEAS"}, {"label": "C", "text": "USG pelvis"}, {"label": "D", "text": "CT abdomen"}]$mmqz$::jsonb,$mmqz$17-hydroxyprogesterone$mmqz$,$mmqz$In a teenager with hyperandrogenism, primary amenorrhoea and a high testosterone, measure 17-hydroxyprogesterone to diagnose non-classical (late-onset) congenital adrenal hyperplasia (21-hydroxylase deficiency).$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q84, p.50$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,NULL,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q087$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$How will you manage a 17-year-old patient with hirsutism and irregular cycles? She is not sexually active.$mmqz$,$mmqz$[{"label": "A", "text": "Cyproterone with ethinyl estradiol"}, {"label": "B", "text": "COCP for 3 months"}, {"label": "C", "text": "COCP for 6 months"}]$mmqz$::jsonb,$mmqz$COCP for 6 months$mmqz$,$mmqz$Cosmetic measures and the combined oral contraceptive pill (COCP) are first-line treatments for hirsutism (including in PCOS). A trial of at least 6 months of COCP is recommended before assessing response. Anti-androgens (e.g. spironolactone) may be added, with effective contraception, if the response is suboptimal after ≥6 months of COCP/cosmetic therapy; ethinylestradiol 35 mcg plus cyproterone acetate is not first-line due to increased adverse effects.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q85, p.50,51$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,$mmqz$[{"url": "/uploads/content-images/emrcog0224-q087-fig1.png", "caption": "Figure 1"}]$mmqz$::jsonb,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q088$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$A patient diagnosed with multiple sclerosis presents with bladder complaints. What is the management?$mmqz$,$mmqz$[{"label": "A", "text": "Oxybutynin"}, {"label": "B", "text": "Clean intermittent self catheterization"}, {"label": "C", "text": "Botox"}]$mmqz$::jsonb,$mmqz$Clean intermittent self catheterization$mmqz$,$mmqz$In multiple sclerosis with bladder dysfunction (incomplete emptying/retention with a significant post-void residual), clean intermittent self catheterization is the appropriate management.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q86, p.51$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,NULL,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q089$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$What is accepting the null hypothesis when it is actually false?$mmqz$,$mmqz$[{"label": "A", "text": "Type 1 error"}, {"label": "B", "text": "Type 2 error"}, {"label": "C", "text": "True positive"}, {"label": "D", "text": "True negative"}]$mmqz$::jsonb,$mmqz$Type 2 error$mmqz$,$mmqz$Failing to reject (accepting) the null hypothesis when it is actually false is a Type II error (false negative, probability = β). Rejecting the null hypothesis when it is actually true is a Type I error (false positive, probability = α).$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q87, p.51$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,$mmqz$[{"url": "/uploads/content-images/emrcog0224-q089-fig1.png", "caption": "Figure 1"}]$mmqz$::jsonb,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q090$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$What is the likelihood of the test to be positive in a diseased person?$mmqz$,$mmqz$[{"label": "A", "text": "Sensitivity"}, {"label": "B", "text": "Specificity"}, {"label": "C", "text": "Negative predictive value"}, {"label": "D", "text": "Positive predictive value"}, {"label": "E", "text": "Positive LR"}]$mmqz$::jsonb,$mmqz$Positive predictive value$mmqz$,$mmqz$Definitions — Sensitivity: the proportion of true positives detected by a test (how well it classifies subjects who truly have the outcome). Specificity: the proportion of true negatives detected. PPV: the probability of true disease when the result is positive. NPV: the probability of no disease when the result is negative.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q88, p.52$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,NULL,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q091$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$Patient was diagnosed as Covid positive. What is described as the likelihood of testing positive in persons who are diseased?$mmqz$,$mmqz$[{"label": "A", "text": "PPV"}, {"label": "B", "text": "NPV"}, {"label": "C", "text": "Sensitivity"}, {"label": "D", "text": "Specificity"}, {"label": "E", "text": "True positive rate"}]$mmqz$::jsonb,$mmqz$Sensitivity$mmqz$,$mmqz$Sensitivity quantifies a test's ability to correctly identify subjects with the disease — the proportion of true positives that are correctly identified by the test (also called the true positive rate). PPV and NPV are related to sensitivity and specificity through disease prevalence.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q89, p.52$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,NULL,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q092$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$Which of the following drugs is to be avoided in a patient with significant aortopathy in Marfan syndrome with an aortic dilatation >40 mm?$mmqz$,$mmqz$[{"label": "A", "text": "IV oxytocin bolus"}, {"label": "B", "text": "Ergometrine"}, {"label": "C", "text": "Carbetocin"}, {"label": "D", "text": "Misoprostol"}, {"label": "E", "text": "Carboprost"}]$mmqz$::jsonb,$mmqz$Ergometrine$mmqz$,$mmqz$In significant aortopathy (Marfan/Loeys–Dietz with aortic dilatation >40 mm, bicuspid aortopathy with dilatation >45 mm, previous aortic dissection, Turner syndrome with aortic size index >25 cm/m2), ergometrine should be avoided because of the risk of hypertension-induced aortic dissection or rupture. First-line uterotonic is oxytocin; second-line options are misoprostol and carboprost.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q90, p.52,53$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,$mmqz$[{"url": "/uploads/content-images/emrcog0224-q092-fig1.png", "caption": "Figure 1"}]$mmqz$::jsonb,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q093$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$Antenatal patient was lost to follow up from 36 weeks. She presented with severe headache a few weeks later. Her evaluation showed elevated liver enzymes and normal platelets. She was taken for caesarean section owing to maternal indications; however, she collapsed on the table and could not be revived. Post-mortem examination showed haemorrhage in the intraventricular, cerebellar and brainstem regions, with death due to coning (herniation) of the cerebellum. What is the probable cause?$mmqz$,$mmqz$[{"label": "A", "text": "Meningitis"}, {"label": "B", "text": "Subarachnoid haemorrhage"}, {"label": "C", "text": "Severe pre-eclampsia"}, {"label": "D", "text": "Intracerebral haemorrhage"}]$mmqz$::jsonb,$mmqz$Severe pre-eclampsia$mmqz$,$mmqz$Pregnancy-associated intracranial haemorrhage (ICH) is an uncommon but life-threatening event contributing to maternal mortality. Pre-eclampsia (and HELLP — haemolysis, elevated liver enzymes, low platelets) is a major risk factor and is associated with poor outcomes in pregnancy-associated ICH. Early symptoms (e.g. vomiting) can be mistaken for morning sickness and missed. The elevated liver enzymes and severe headache point to severe pre-eclampsia as the underlying cause.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q91, p.53,54$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,NULL,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q094$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$What is the specimen of choice for the diagnosis of chlamydia?$mmqz$,$mmqz$[{"label": "A", "text": "Vulvo-vaginal swab (VVS)"}, {"label": "B", "text": "Endocervical swab"}, {"label": "C", "text": "Urethral swab"}, {"label": "D", "text": "First-catch urine"}, {"label": "E", "text": "High vaginal swab"}]$mmqz$::jsonb,$mmqz$Vulvo-vaginal swab (VVS)$mmqz$,$mmqz$A vulvo-vaginal swab (VVS) is the specimen of choice in women. It is collected by inserting a dry swab about 2–3 inches into the vagina and rotating for 10–30 seconds, has a sensitivity of 96–98%, and can be taken by the patient or a healthcare worker. VVS sensitivities are higher than cervical swabs and are more acceptable to women than urine or cervical specimens.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q92, p.54$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,NULL,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q095$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$Following a surgery for a benign gynaecological procedure, patient complained of cough with greenish sputum, chest pain and dyspnoea. Examination showed high-grade fever, crepitations and features of lung consolidation. What is the most probable causative organism?$mmqz$,$mmqz$[{"label": "A", "text": "Streptococcus pneumoniae"}, {"label": "B", "text": "Influenza virus"}, {"label": "C", "text": "Respiratory syncytial virus"}]$mmqz$::jsonb,$mmqz$Streptococcus pneumoniae$mmqz$,$mmqz$Post-operative bacterial pneumonia with fever, consolidation and productive cough is most commonly caused by Streptococcus pneumoniae. Sputum colour may suggest the pathogen: S. pneumoniae classically rust-coloured (pneumococcal species may also produce green sputum), Klebsiella red currant-jelly, Pseudomonas/Haemophilus green, anaerobes foul-smelling.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q93, p.54,55$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,$mmqz$[{"url": "/uploads/content-images/emrcog0224-q095-fig1.png", "caption": "Figure 1"}]$mmqz$::jsonb,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q096$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$Following a surgery for a benign gynaecological procedure, patient complained of cough with greenish sputum, chest pain, dyspnoea and fever. ABG shows a picture of hypoxia and hypercapnia with respiratory acidosis. What is the probable cause?$mmqz$,$mmqz$[{"label": "A", "text": "Respiratory failure"}, {"label": "B", "text": "Pneumonia"}, {"label": "C", "text": "Opiate toxicity"}]$mmqz$::jsonb,$mmqz$Pneumonia$mmqz$,$mmqz$Fever, productive cough, consolidation and an ABG showing hypoxia with hypercapnia/respiratory acidosis in this post-operative patient indicate pneumonia (with type 2 respiratory failure secondary to it).$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q94, p.55$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,$mmqz$[{"url": "/uploads/content-images/emrcog0224-q096-fig1.png", "caption": "Figure 1"}]$mmqz$::jsonb,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q097$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$What is the detection rate of the combined test for trisomy 21?$mmqz$,$mmqz$[{"label": "A", "text": "90%"}, {"label": "B", "text": "95%"}, {"label": "C", "text": "85%"}, {"label": "D", "text": "99%"}]$mmqz$::jsonb,$mmqz$90%$mmqz$,$mmqz$The first-trimester combined test detects about 90% of trisomy 21 with a false-positive rate of about 5%. For comparison: double test 60–65%, triple test 65–70%, quadruple test 70–75%, and cell-free DNA (NIPT) about 99% (false positive 0.1%).$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q95, p.55,56$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,$mmqz$[{"url": "/uploads/content-images/emrcog0224-q097-fig1.png", "caption": "Figure 1"}]$mmqz$::jsonb,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q098$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$What is the success rate of the McRoberts' manoeuvre in managing shoulder dystocia?$mmqz$,$mmqz$[{"label": "A", "text": "85%"}, {"label": "B", "text": "90%"}, {"label": "C", "text": "95%"}, {"label": "D", "text": "100%"}]$mmqz$::jsonb,$mmqz$90%$mmqz$,$mmqz$The McRoberts' manoeuvre is an effective intervention with reported success rates as high as 90%. It has a low complication rate and is one of the least invasive manoeuvres, so should be employed first. (The 'all-fours' position has an ~83% success rate in one case series.)$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q96, p.56$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,NULL,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
