INSERT INTO content_blocks (id,topic_id,type,content,"order",created_at) VALUES ($mmqz$emrcog-jul2024-02-note099-img2$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$image$mmqz$,$mmqz$/uploads/content-images/emrcog0224-q099-fig2.png$mmqz$,992,now()) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content,type=EXCLUDED.type;
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q100$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$What is the recommended maximum insufflation pressure for the placement of the primary port in laparoscopy in a pregnant patient at 22 weeks of gestation?$mmqz$,$mmqz$[{"label": "A", "text": "20 mmHg"}, {"label": "B", "text": "25 mmHg"}, {"label": "C", "text": "12 mmHg"}, {"label": "D", "text": "10 mmHg"}, {"label": "E", "text": "8 mmHg"}]$mmqz$::jsonb,$mmqz$25 mmHg$mmqz$,$mmqz$Pneumoperitoneum in pregnancy: an intra-abdominal pressure of 20–25 mmHg should be used for gas insufflation before inserting the primary trocar (so the maximum is 25 mmHg). Current evidence supports operating pressures of 12 mmHg. As these higher pressures are only maintained briefly until the primary port is placed, they are unlikely to harm the fetus.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q98, p.57$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,$mmqz$[{"url": "/uploads/content-images/emrcog0224-q100-fig1.png", "caption": "Figure 1"}]$mmqz$::jsonb,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q101$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$Evaluation of a patient with recurrent first-trimester loss shows a normal 3D USG of the uterus. Blood report ruled out APLA. She has a positive family history of thrombophilia. What is the appropriate investigation?$mmqz$,$mmqz$[{"label": "A", "text": "OGTT"}, {"label": "B", "text": "TORCH"}, {"label": "C", "text": "Anti-thyroid antibodies"}, {"label": "D", "text": "Genetic screening"}, {"label": "E", "text": "Factor V Leiden"}]$mmqz$::jsonb,$mmqz$Factor V Leiden$mmqz$,$mmqz$With a positive family history of thrombophilia and antiphospholipid antibodies excluded, test for inherited thrombophilia — Factor V Leiden (and prothrombin gene mutation and protein S deficiency), ideally within a research context.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q99, p.57$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,NULL,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q102$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$Which of the following is associated with recurrent miscarriage?$mmqz$,$mmqz$[{"label": "A", "text": "Factor V Leiden"}, {"label": "B", "text": "Protein S"}, {"label": "C", "text": "Prothrombin gene mutation"}, {"label": "D", "text": "Protein C"}]$mmqz$::jsonb,$mmqz$Factor V Leiden$mmqz$,$mmqz$Factor V Leiden appears to be associated with first and particularly second trimester recurrent miscarriages. Prothrombin gene mutation is associated with recurrent miscarriage. Protein S deficiency has not demonstrated a consistent association with recurrent first trimester miscarriage, but has shown an association with second trimester. Protein C deficiency has not shown a consistent association with recurrent miscarriage. MTHFR mutation (heterozygous and homozygous) has been found to have a significant association with recurrent miscarriage in one meta-analysis from China; however other meta-analyses did not find an association and advise against testing for it. Antithrombin deficiency is the rarer yet most thrombogenic mutation; the EPCOT study found only a possible association with sporadic miscarriage while a subsequent meta-analysis did not.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q100, p.58$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,$mmqz$[{"url": "/uploads/content-images/emrcog0224-q102-fig1.png", "caption": "Figure 1"}]$mmqz$::jsonb,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q103$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$What is the next step in managing a patient with recurrent postmenopausal bleeding on combined hormonal replacement therapy? Patient continued to have recurrent bleed despite alteration in progesterone dose.$mmqz$,$mmqz$[{"label": "A", "text": "Tvs"}, {"label": "B", "text": "Pipelle biopsy"}, {"label": "C", "text": "Hysteroscopy"}, {"label": "D", "text": "Stop HRT"}, {"label": "E", "text": "Give COC"}]$mmqz$::jsonb,$mmqz$Tvs$mmqz$,$mmqz$For unscheduled bleeding on HRT: assess cancer risk factors and bleeding pattern, identify HRT regimen/duration/compliance, and offer examination/investigations. Arrange urgent transvaginal ultrasound (within 6 weeks) if there is 1 major or 3 minor risk factors for endometrial cancer, or heavy/persistent bleeding, 2 minor risk factors, more than 6 months since starting HRT, or more than 3 months after a change in dose or preparation. Ultrasound thresholds prompting endometrial assessment: sHRT ET > 7 mm, ccHRT ET > 4 mm, or endometrium incompletely visualised. Management options for persistent unscheduled bleeding include changing to an oral preparation, offering the 52 mg LNG-IUD, increasing the progestogen dose or switching to a synthetic progestogen, a 3-month trial of an additional progestogen, and reducing the estrogen dose.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q101, p.58,59$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,$mmqz$[{"url": "/uploads/content-images/emrcog0224-q103-fig1.png", "caption": "Figure 1"}]$mmqz$::jsonb,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q104$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$Test to diagnose hyperandrogenism in PCOS.$mmqz$,$mmqz$[{"label": "A", "text": "Free Testosterone"}, {"label": "B", "text": "Free androgen index"}, {"label": "C", "text": "17 OHP"}, {"label": "D", "text": "LH and FSH"}]$mmqz$::jsonb,$mmqz$Free Testosterone$mmqz$,$mmqz$Use total testosterone and free testosterone for diagnosis of hyperandrogenism in PCOS. If not elevated, then androstenedione and dehydroepiandrosterone sulfate (DHEA-S) could be measured, but are less specific with a limited role in PCOS diagnosis.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q102, p.59,60$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,$mmqz$[{"url": "/uploads/content-images/emrcog0224-q104-fig1.png", "caption": "Figure 1"}]$mmqz$::jsonb,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q105$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$How will you manage a woman with PCOS presenting with 18 months amenorrhea?$mmqz$,$mmqz$[{"label": "A", "text": "Cyclical progesterone"}, {"label": "B", "text": "Coc"}, {"label": "C", "text": "Laparoscopic ovarian drilling"}, {"label": "D", "text": "Hysteroscopy and Endometrial biopsy"}]$mmqz$::jsonb,$mmqz$Cyclical progesterone$mmqz$,$mmqz$Oligo- or amenorrhoea in women with PCOS may predispose to endometrial hyperplasia and later carcinoma. It is good practice to recommend treatment with gestogens to induce a withdrawal bleed at least every 3 to 4 months. Transvaginal ultrasound should be considered in the absence of withdrawal bleeds or abnormal uterine bleeding. In PCOS, an endometrial thickness of less than 7 mm is unlikely to be hyperplasia. A thickened endometrium or an endometrial polyp should prompt consideration of endometrial biopsy and/or hysteroscopy.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q103, p.60$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,NULL,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q106$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$How will you manage a woman with PCOS presenting with 18 months amenorrhea with an endometrial thickness of 7mm?$mmqz$,$mmqz$[{"label": "A", "text": "Cyclical progesterone"}, {"label": "B", "text": "Coc"}, {"label": "C", "text": "Laparoscopic ovarian drilling"}, {"label": "D", "text": "Hysteroscopy and Endometrial biopsy"}]$mmqz$::jsonb,$mmqz$Cyclical progesterone$mmqz$,$mmqz$Cyclical progesterone (gestogens) is recommended to induce a withdrawal bleed. In PCOS an endometrial thickness below 7 mm is unlikely to be hyperplasia, so at 7 mm cyclical progesterone remains appropriate; a clearly thickened endometrium or a polyp would prompt endometrial biopsy and/or hysteroscopy. Progestin-only oral contraceptives may be considered for endometrial protection, based on general population guidelines, acknowledging that evidence in women with PCOS is limited. COCP is first-line pharmacological therapy for hyperandrogenism and irregular cycles.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q104, p.60,61$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,$mmqz$[{"url": "/uploads/content-images/emrcog0224-q106-fig1.png", "caption": "Figure 1"}]$mmqz$::jsonb,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q107$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$38 year old, P2, presented with amenorrhoea for 18 months after the delivery of her second child. During her delivery she had PPH, retained placenta was removed under GA and 1 unit of blood was transfused. Postpartum period was uneventful and she breastfed her baby. Her hormonal evaluation showed: Prolactin high, estradiol 2430. What is the probable cause?$mmqz$,$mmqz$[{"label": "A", "text": "Sheehan's syndrome"}, {"label": "B", "text": "Pregnancy"}, {"label": "C", "text": "Ovarian tumour"}]$mmqz$::jsonb,$mmqz$Pregnancy$mmqz$,$mmqz$A markedly high estradiol (2430) together with high prolactin in a woman with amenorrhoea points to pregnancy. Sheehan's syndrome (postpartum pituitary necrosis after PPH) causes hypopituitarism with low estradiol and failure of lactation, not a high estradiol, so the elevated estradiol here is consistent with pregnancy rather than Sheehan's syndrome.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q105, p.61$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,NULL,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q108$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$GARDASIL 9 protects against what types of HPV?$mmqz$,$mmqz$[{"label": "A", "text": "6, 11"}, {"label": "B", "text": "6, 11, 16, 18"}, {"label": "C", "text": "6, 11, 16, 18, 31, 33, 45, 52, 58"}]$mmqz$::jsonb,$mmqz$6, 11, 16, 18, 31, 33, 45, 52, 58$mmqz$,$mmqz$Cervarix (protecting against HPV types 16 and 18) was offered from September 2008 until September 2012, when Gardasil (protecting against HPV 16 and 18 plus 6 and 11, which cause genital warts) replaced it. In summer 2022, Gardasil 9 was introduced to replace Gardasil. The 9-valent vaccine protects against 5 additional cancer-causing HPV types (31, 33, 45, 52, 58), giving protection against 9 HPV types in total: 6, 11, 16, 18, 31, 33, 45, 52, 58. Gardasil 9 is currently supplied for those eligible (adolescents aged 12-13 and those eligible until age 25, and GBMSM up to and including 45 years).$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q106, p.61$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,$mmqz$[{"url": "/uploads/content-images/emrcog0224-q108-fig1.png", "caption": "Figure 1"}]$mmqz$::jsonb,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q109$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$How will you confirm a case of diabetes insipidus in pregnancy?$mmqz$,$mmqz$[{"label": "A", "text": "LDH"}, {"label": "B", "text": "Serum electrolytes"}, {"label": "C", "text": "Full blood count"}, {"label": "D", "text": "Blood osmolality"}]$mmqz$::jsonb,$mmqz$Blood osmolality$mmqz$,$mmqz$Diabetes insipidus (DI) classically presents with polydipsia and dilute polyuria. Diagnosis is made after excluding other causes of polyuria (diuretics, hyperglycaemia, hypercalcaemia, hypokalaemia and renal tubular acidosis). Gestational DI should be considered when blood osmolality is consistent with nonpregnant levels (i.e. >285 mOsmol/kg) with urinary osmolality <300 mOsmol/kg. Women may have borderline high serum sodium (within normal limits but elevated for pregnancy). Serum ADH can be assayed with a vasopressinase inhibitor to distinguish a central lack of production from degradation by placental vasopressinase; chromatography can measure vasopressinase activity. Vasopressin treatment differentiates DI types, as central and gestational DI result from a lack of circulating ADH. Pituitary function tests (TFTs, prolactin) may be performed to look for panhypopituitarism. Table 2 summary: presenting symptoms polyuria (>3 L/day), polydipsia (>3 L/day) and hypernatraemia (weakness, confusion, seizures); investigations urea and electrolytes, Ca2+, glucose; serum and urine osmolality; urine specific gravity low, usually <1.005.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q107, p.62,63$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,$mmqz$[{"url": "/uploads/content-images/emrcog0224-q109-fig1.png", "caption": "Figure 1"}]$mmqz$::jsonb,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q110$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$A couple was evaluated for subfertility and diagnosed to be due to anovulation. The female was started on clomifene citrate. On day 21 of the cycle, the patient presented with acute pelvic pain which was relieved with paracetamol. What is the probable cause?$mmqz$,$mmqz$[{"label": "A", "text": "PID"}, {"label": "B", "text": "Subacute torsion"}, {"label": "C", "text": "Mittelschmerz"}, {"label": "D", "text": "Ohss"}, {"label": "E", "text": "Tubal Hydrocele"}]$mmqz$::jsonb,$mmqz$Ohss$mmqz$,$mmqz$This is OHSS. The timing of presentation following the trigger injection divides patients into early and late OHSS. Early OHSS usually presents within 7 days of the hCG injection and is associated with an excessive ovarian response. Late OHSS typically presents 10 or more days after the hCG injection and usually results from endogenous hCG derived from an early pregnancy; the preceding ovarian response may be unremarkable, and late OHSS tends to be more prolonged and severe than the early form. Clomifene-induced ovulation with day-21 pelvic pain relieved by simple analgesia is consistent with OHSS rather than PID, torsion, mittelschmerz or hydrocele.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q108, p.63$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,NULL,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q111$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$What is the most common reason for transfer from homebirth to an obstetric unit?$mmqz$,$mmqz$[{"label": "A", "text": "Delay during first or second stage of labour"}, {"label": "B", "text": "Fetal distress"}, {"label": "C", "text": "Meconium stained liquor"}]$mmqz$::jsonb,$mmqz$Delay during first or second stage of labour$mmqz$,$mmqz$Delay during the first or second stage of labour is the most common reason for transfer to an obstetric unit from all birth settings. Table 1 shows the primary reasons for transfer: delay in the first or second stage of labour accounts for 1,144 (32.4%) transfers from home, 912 (37.1%) from freestanding midwifery units and 1,548 (35.2%) from alongside midwifery units, making it the leading reason in each setting, ahead of meconium staining, repair of perineal trauma and abnormal fetal heart rate.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q109, p.63,64$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,$mmqz$[{"url": "/uploads/content-images/emrcog0224-q111-fig1.png", "caption": "Figure 1"}]$mmqz$::jsonb,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q112$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$Patient suffered myocardial infarction at 35 weeks of gestation. What is your advice regarding delivery?$mmqz$,$mmqz$[{"label": "A", "text": "Delay delivery for 2 wks"}, {"label": "B", "text": "4 weeks"}, {"label": "C", "text": "Instrumental delivery with epidural analgesia"}]$mmqz$::jsonb,$mmqz$Delay delivery for 2 wks$mmqz$,$mmqz$Timing and mode of delivery after acute myocardial infarction (AMI): there are no standardised guidelines because of the lack of prospective data and the variation in individual patient characteristics. Collaborative management involving a cardiologist, obstetric physician, obstetrician, obstetric anaesthetist and neonatologist guides care, individualised to maternal cardiac status and gestational age. If there is a risk of preterm delivery, maternal steroid injections should be administered at the earliest opportunity. If possible, delivery should be delayed by 2 to 3 weeks following AMI because of the increased risk of maternal mortality during this time.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q110, p.64$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,$mmqz$[{"url": "/uploads/content-images/emrcog0224-q112-fig1.png", "caption": "Figure 1"}]$mmqz$::jsonb,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q113$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$DIC marker: scenario of a patient who presented with IUFD with normal fibrinogen 1.9, prolonged APTT 37 (ref 35) and low platelets (130000). Which among the following is a pointer for DIC?$mmqz$,$mmqz$[{"label": "A", "text": "Fibrinogen"}, {"label": "B", "text": "APTT"}, {"label": "C", "text": "Low Platelets"}]$mmqz$::jsonb,$mmqz$Low Platelets$mmqz$,$mmqz$After a late intrauterine fetal death there is a moderate risk of maternal disseminated intravascular coagulation (DIC): about 10% within 4 weeks of the IUFD, rising to 30% thereafter. It is tested for by clotting studies, blood platelet count and fibrinogen measurement. A down-trending platelet count is often the first laboratory abnormality to be noted; a trend toward decreasing platelets or a grossly reduced absolute platelet count is a sensitive (though not specific) indicator of DIC. Other tests include prothrombin time (PT-INR), activated partial thromboplastin time (aPTT), D-dimer and fibrinogen level; the D-dimer test is the most sensitive single laboratory test for diagnosing DIC. In this scenario the fibrinogen (1.9) is normal and the APTT (37, ref 35) is only marginally raised, so the low platelet count (130000) is the pointer to DIC.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q111, p.65$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,$mmqz$[{"url": "/uploads/content-images/emrcog0224-q113-fig1.png", "caption": "Figure 1"}]$mmqz$::jsonb,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q114$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$What is the possible etiology in a pregnancy showing hydrocephalus, holoprosencephaly, FGR and placental cysts on the anomaly scan?$mmqz$,$mmqz$[{"label": "A", "text": "Edward syndrome"}, {"label": "B", "text": "Triploidy"}, {"label": "C", "text": "Turner syndrome"}, {"label": "D", "text": "Patau syndrome"}, {"label": "E", "text": "Down syndrome"}]$mmqz$::jsonb,$mmqz$Triploidy$mmqz$,$mmqz$Triploid syndrome (triploidy) is a chromosomal disorder in which the fetus has three copies of every chromosome instead of the normal two. CNS features include holoprosencephaly, hydrocephalus (increased cerebrospinal fluid within the brain), ventriculomegaly, Arnold-Chiari malformation, agenesis of the corpus callosum and neural tube defects. Triploid fetuses have intrauterine growth restriction beginning early in pregnancy, as early as 12 weeks, which does not affect the head as severely as the body. Oligohydramnios is common in triploid pregnancies. Placental abnormalities are common in triploidy; most frequently the placenta is enlarged and may contain cysts.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q112, p.65,66$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,NULL,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q115$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$What is the rate of persistent trophoblastic disease in ectopic pregnancy managed by salpingotomy?$mmqz$,$mmqz$[{"label": "A", "text": "1%"}, {"label": "B", "text": "10%"}, {"label": "C", "text": "7%"}, {"label": "D", "text": "15%"}, {"label": "E", "text": "20%"}]$mmqz$::jsonb,$mmqz$7%$mmqz$,$mmqz$Persistent trophoblast occurred more frequently in the salpingotomy group (14 [7%] versus 1 [less than 1%]; relative risk [RR] 15.0, 95% CI 2.0-113.4). Studies have reported persistent trophoblast rates of 3.9-11.0% after salpingotomy. Factors suggested as increasing the risk of persistent trophoblast include higher preoperative serum beta-hCG levels, a rapid preoperative rise in serum beta-hCG and larger tubal masses. Inform women having a salpingotomy that up to 1 in 5 women may need further treatment.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q113, p.66$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,NULL,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q116$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$Patient is taken up for CS at full dilatation. During the procedure, the surgeon encountered difficulty in delivering the deeply impacted fetal head. What is the best method employed in such situations?$mmqz$,$mmqz$[{"label": "A", "text": "Breech extraction"}, {"label": "B", "text": "Push method"}, {"label": "C", "text": "Employing fetal pillow"}, {"label": "D", "text": "Abdominal cephalic disimpaction"}, {"label": "E", "text": "Reverse breech extraction"}, {"label": "F", "text": "Administer nitroglycerine"}]$mmqz$::jsonb,$mmqz$Abdominal cephalic disimpaction$mmqz$,$mmqz$Impaction of the fetal head can leave a lack of space for the operator to insert their hand anteriorly between the fetal head and pubic symphysis, hindering the standard approach to deliver the head at caesarean birth (CB). Abdominal cephalic disimpaction (using the dominant or non-dominant hand to flex and lift the baby's head upwards into the maternal abdomen) is likely to be effective in the majority of cases of impacted fetal head (IFH) at CB. If the obstetrician is unable to disimpact the head with these standard manoeuvres, several strategies can be employed, including tocolysis, vaginal disimpaction (push-up), reverse breech extraction and the Patwardhan method. There is a lack of consensus regarding which technique is safest or most effective. Non-recommended techniques: a single forceps blade or ventouse used abdominally, or bladder filling, are not supported by evidence; use of a vacuum at CB can cause significant fetal injury (intracranial and subgaleal haemorrhage) and should be avoided. The algorithm for IFH at caesarean section summarises anticipate and prepare, diagnose IFH, declare the emergency, call for help, pause, consider tocolysis, abdominal cephalic disimpaction (A), consider changing hands, then vaginal disimpaction (B) or reverse breech extraction (C), and repeating the above or considering the Patwardhan manoeuvre.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q114, p.67,68$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,$mmqz$[{"url": "/uploads/content-images/emrcog0224-q116-fig1.png", "caption": "Figure 1"}, {"url": "/uploads/content-images/emrcog0224-q116-fig2.png", "caption": "Figure 2"}]$mmqz$::jsonb,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q117$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$Patient presented with primary amenorrhea. Examination showed a blind-ending vagina, Tanner 2/5 breast development, scanty pubic hair and axillary hair.$mmqz$,$mmqz$[{"label": "A", "text": "MRKH"}, {"label": "B", "text": "AIS"}, {"label": "C", "text": "Turner syndrome"}]$mmqz$::jsonb,$mmqz$AIS$mmqz$,$mmqz$This is androgen insensitivity syndrome (AIS). Disorders of androgen action are a common form of 46,XY differences of sex development (DSD); loss-of-function mutations in the androgen receptor (AR) lead to variable loss of virilization. In complete AIS the external genitalia are completely female with a short/blind-ending vagina, gonads are mostly abdominal or inguinal, puberty brings feminization with sparse-to-absent secondary sexual hair, and post-pubertal gonadectomy is favoured. In partial AIS there is clitoromegaly, a narrow vagina and variable labial fusion, mostly inguinal gonads, breast development with slight virilization, and pre-pubertal gonadectomy is favoured. A blind-ending vagina with breast development but scanty pubic and axillary hair fits AIS rather than MRKH (which has normal pubic/axillary hair) or Turner syndrome.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q115, p.69$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,$mmqz$[{"url": "/uploads/content-images/emrcog0224-q117-fig1.png", "caption": "Figure 1"}]$mmqz$::jsonb,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q118$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$65 year old patient presented with moderate rectocele and urge incontinence. What is the initial management?$mmqz$,$mmqz$[{"label": "A", "text": "Supervised pelvic floor exercise + bladder retraining"}, {"label": "B", "text": "Bladder diary"}, {"label": "C", "text": "Bladder retraining"}, {"label": "D", "text": "Supervised pelvic floor exercise"}]$mmqz$::jsonb,$mmqz$Bladder diary$mmqz$,$mmqz$Use bladder diaries in the initial assessment of women with urinary incontinence or overactive bladder. Encourage women to complete a minimum of 3 days of the diary covering variations in their usual activities, such as both working and leisure days.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q116, p.69,70$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,NULL,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q119$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$Patient with a history of failed mid-urethral sling surgery for SUI. What is the best investigation?$mmqz$,$mmqz$[{"label": "A", "text": "Urodynamic"}, {"label": "B", "text": "Cystoscopy"}]$mmqz$::jsonb,$mmqz$Urodynamic$mmqz$,$mmqz$After failed continence surgery, urodynamic studies are recommended before considering further surgical treatment, to characterise the underlying bladder dysfunction (stress incontinence, detrusor overactivity or voiding difficulty).$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q117, p.70$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,NULL,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q120$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$Pregnant patient presented with a painful swollen left leg. She was commenced on LMWH. How to evaluate her further?$mmqz$,$mmqz$[{"label": "A", "text": "Duplex scanning of Left leg"}, {"label": "B", "text": "Duplex scanning of both legs"}]$mmqz$::jsonb,$mmqz$Duplex scanning of Left leg$mmqz$,$mmqz$Compression duplex ultrasound of the symptomatic (left) leg is the initial investigation for suspected DVT in pregnancy. If the initial scan is negative but clinical suspicion of DVT remains, anticoagulation is continued and the scan is repeated.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q118, p.70$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,NULL,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q121$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$Patient in labour with continuous fetal heart rate monitoring. At 4 cm dilatation, the CTG showed a baseline above 180 bpm. What is the best management?$mmqz$,$mmqz$[{"label": "A", "text": "fetal scalp stimulation"}, {"label": "B", "text": "perform fetal blood sampling"}, {"label": "C", "text": "administer tocolysis"}, {"label": "D", "text": "undertake conservative measures"}, {"label": "E", "text": "evaluate the whole clinical picture and consider expediting birth"}]$mmqz$::jsonb,$mmqz$evaluate the whole clinical picture and consider expediting birth$mmqz$,$mmqz$A fetal heart rate baseline above 180 bpm is an abnormal (pathological) feature. Management is not a single isolated action; the whole clinical picture should be evaluated. If the CTG trace is categorised as pathological: obtain an urgent review by an obstetrician and a senior midwife; exclude acute events (e.g. cord prolapse, suspected placental abruption or suspected uterine rupture) that need immediate intervention; perform a full risk assessment including a full set of maternal observations, taking into account the whole clinical picture, and document the findings; and consider possible underlying causes and undertake conservative measures. If the trace is still pathological after conservative measures: obtain a further urgent review, evaluate the whole clinical picture and consider expediting birth; if there are evolving intrapartum risk factors for fetal compromise, have a very low threshold for expediting birth.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q119, p.70$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,$mmqz$[{"url": "/uploads/content-images/emrcog0224-q121-fig1.png", "caption": "Figure 1"}]$mmqz$::jsonb,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q122$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$Labouring woman was on continuous fetal monitoring with CTG. The trace showed variable deceleration with shouldering for 30 minutes at 7 cm dilatation. What is the next step?$mmqz$,$mmqz$[{"label": "A", "text": "Fetal blood sampling"}, {"label": "B", "text": "Expedite birth"}, {"label": "C", "text": "Start conservative measures"}, {"label": "D", "text": "Continue ctg"}]$mmqz$::jsonb,$mmqz$Continue ctg$mmqz$,$mmqz$Regard the following as concerning characteristics of variable decelerations: lasting more than 60 seconds; reduced variability within the deceleration; failure or slow return to the baseline fetal heart rate; and loss of previously present shouldering. Variable decelerations WITH shouldering that persist for 30 minutes but have none of these concerning characteristics are not pathological, so the appropriate step is to continue the CTG.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q120, p.71$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,NULL,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q123$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$Patient in labour with good descent and progression. CTG shows a baseline at 160, variability 2-4 for 45 minutes. What is the management?$mmqz$,$mmqz$[{"label": "A", "text": "Cs"}, {"label": "B", "text": "Fetal scalp stimulation"}, {"label": "C", "text": "Continue ctg"}, {"label": "D", "text": "Fetal scalp stimulation"}, {"label": "E", "text": "Conservative measures"}]$mmqz$::jsonb,$mmqz$Conservative measures$mmqz$,$mmqz$A baseline of 160 with reduced variability (2-4) for 45 minutes represents a suspicious CTG. If the CTG is suspicious and there are no other concerning risk factors: perform a full risk assessment (a full set of maternal observations and the whole clinical picture) and document; note that if accelerations are present fetal acidosis is unlikely; if the trace was previously normal, consider underlying reasons for the change; and undertake conservative measures. If suspicious with additional intrapartum risk factors (slow progress, sepsis or meconium): full risk assessment, conservative measures, obtain an urgent review by an obstetrician or senior midwife, and consider fetal scalp stimulation or expediting birth. With good descent and progression and no additional risk factors, conservative measures are appropriate.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q121, p.71,72$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,$mmqz$[{"url": "/uploads/content-images/emrcog0224-q123-fig1.png", "caption": "Figure 1"}]$mmqz$::jsonb,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q124$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$A primigravida is in spontaneous preterm labour at 35 + 1 weeks of gestation. She has progressed satisfactorily and has been pushing for 15 minutes. Fifteen minutes prior to pushing, a suspicious CTG was noted. Baby passed meconium. You are not able to feel the fetal head abdominally and the vertex is at +1 station. Conservative measures failed to improve the fetal heart rate. What is the most appropriate course of action?$mmqz$,$mmqz$[{"label": "A", "text": "Expedite delivery by performing a caesarean section"}, {"label": "B", "text": "Expedite delivery with mid-cavity forceps"}, {"label": "C", "text": "Expedite delivery with rotational forceps"}, {"label": "D", "text": "Expedite delivery with Ventouse"}, {"label": "E", "text": "perform fetal blood sampling"}]$mmqz$::jsonb,$mmqz$Expedite delivery with mid-cavity forceps$mmqz$,$mmqz$At preterm gestations, operators should be aware of a higher risk of subgaleal haemorrhage and scalp trauma with vacuum extraction compared with forceps. Vacuum birth should be avoided below 32 weeks of gestation and should be used with caution between 32+0 and 36+0 weeks. At 35+1 weeks with a suspicious CTG unresponsive to conservative measures, the head not palpable abdominally and the vertex at +1 station (mid-cavity), expediting delivery with mid-cavity forceps is most appropriate; ventouse is cautioned at this gestation because of the higher risk of scalp trauma and subgaleal haemorrhage.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q122, p.72,73$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,NULL,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q125$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$Multiparous patient in labour with a diagnosed delay in delivery. Examination now shows vertex at +1 OA position.$mmqz$,$mmqz$[{"label": "A", "text": "Midcavity delivery in labour room"}, {"label": "B", "text": "Trial of instrumental delivery in theatre"}, {"label": "C", "text": "Ventouse delivery in labour room"}]$mmqz$::jsonb,$mmqz$Trial of instrumental delivery in theatre$mmqz$,$mmqz$A vertex at +1 station is at the mid-cavity level. With delay in the second stage and the vertex at +1 in the OA position, a trial of instrumental (non-rotational) delivery should be conducted in theatre, where there is immediate recourse to caesarean section if the trial fails, rather than in the labour room, because mid-cavity deliveries carry a higher risk of failure.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q123, p.73$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,NULL,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q126$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$Patient presented with ataxia, irregular menses and learning disability. Examination also showed cataract. What is the probable cause?$mmqz$,$mmqz$[{"label": "A", "text": "Galactosemia"}, {"label": "B", "text": "Turner syndrome"}]$mmqz$::jsonb,$mmqz$Galactosemia$mmqz$,$mmqz$This is classic galactosemia. Affected adolescents and adults often have focal neurologic findings such as tremor, ataxia and dysmetria (impaired ability to control actions). Together with cataracts, primary/premature ovarian insufficiency (irregular menses) and learning disability, the picture points to galactosemia rather than Turner syndrome.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q124, p.73$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,NULL,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q127$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$Pregnant mother presented with absent fetal movements. Diagnosed with IUFD at 22 weeks. She chose conservative management and delivered at 24 weeks. How would you define this delivery?$mmqz$,$mmqz$[{"label": "A", "text": "Miscarriage"}, {"label": "B", "text": "Stillbirth"}]$mmqz$::jsonb,$mmqz$Stillbirth$mmqz$,$mmqz$Stillbirth is defined by the gestation at birth, irrespective of when the death occurred. Deaths eligible for reporting to MBRRACE-UK: Late fetal losses - a baby born at 22 or 23 completed weeks' gestation showing no signs of life, irrespective of when death occurred. Stillbirths - a baby born from 24 completed weeks' gestation (or from 400 g where an accurate gestation is not available) showing no signs of life, irrespective of when death occurred. Neonatal deaths - the death of a live-born baby, born from 20 completed weeks' gestation, occurring before 28 completed days after birth. Here the intrauterine death occurred at 22 weeks but the baby was delivered at 24 weeks, so by gestation at birth it is classified as a stillbirth.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q125, p.73$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,$mmqz$[{"url": "/uploads/content-images/emrcog0224-q127-fig1.png", "caption": "Figure 1"}]$mmqz$::jsonb,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q128$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$Patient on methadone collapsed with pinpoint pupils. What is the management?$mmqz$,$mmqz$[{"label": "A", "text": "Iv naloxone"}, {"label": "B", "text": "Im naloxone"}, {"label": "C", "text": "Intranasal naloxone"}]$mmqz$::jsonb,$mmqz$Iv naloxone$mmqz$,$mmqz$Give intravenous naloxone. The British National Formulary (BNF) recommends reversing acute opioid/opiate overdose in adults by intravenous injection of naloxone 400 micrograms to 2 mg; if there is no response, repeat at intervals of two to three minutes to a maximum of 10 mg. Doses used in acute overdose may not be appropriate for opioid-induced respiratory depression and sedation in palliative care or chronic opioid use, where the recommended IV dose is 100 to 200 micrograms (1.5 to 3 micrograms/kg), with subsequent 100 microgram doses every two minutes if the response is inadequate. Careful monitoring of vital observations and maintenance of pain relief are still required.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q126, p.73,74,75$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,$mmqz$[{"url": "/uploads/content-images/emrcog0224-q128-fig1.png", "caption": "Figure 1"}]$mmqz$::jsonb,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q129$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$Patient on 70 ml of methadone was observed to be lost from the ward and found unconscious near the toilet. Examination showed a weak and thready pulse. How to manage?$mmqz$,$mmqz$[{"label": "A", "text": "IV adrenalin"}, {"label": "B", "text": "IM adrenalin"}, {"label": "C", "text": "IV Naloxone"}, {"label": "D", "text": "IM Naloxone"}]$mmqz$::jsonb,$mmqz$IV Naloxone$mmqz$,$mmqz$This is opioid (methadone) overdose causing reduced consciousness and cardiovascular compromise (weak, thready pulse). The management is intravenous naloxone, an opioid antagonist; adrenaline is not the treatment for opioid overdose. Naloxone is given by the intravenous route (preferred) for its quicker onset of action and is titrated to response. Emergency treatment of opioid overdose: initial dose 400 micrograms IV; if no response after 1 minute give 800 micrograms; repeat 800 micrograms after a further minute if still no response; if still no response give 2 mg (up to 4 mg in a seriously poisoned patient), then review the diagnosis.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q127, p.75$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,NULL,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q130$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$How will you monitor an early-onset FGR fetus growing at the 3rd centile with an absent umbilical artery Doppler?$mmqz$,$mmqz$[{"label": "A", "text": "Daily cCTG"}, {"label": "B", "text": "Daily DV doppler"}, {"label": "C", "text": "Alternate every 2-3 days: DV doppler"}, {"label": "D", "text": "Alternate days: umbilical artery doppler - DV and cCTG"}]$mmqz$::jsonb,$mmqz$Alternate days: umbilical artery doppler - DV and cCTG$mmqz$,$mmqz$In early-onset FGR the intensity of surveillance is guided by the severity of the Doppler abnormality. Absent end-diastolic flow (EDF) in the umbilical artery is a pre-critical finding. Borderline (UA PI >95th centile, DV PIV raised >95th centile): repeat umbilical artery Doppler, DV Doppler and CTG every week. Pre-critical (absent EDF in the UA, absent DV a-wave): alternate daily umbilical artery Doppler and DV Doppler and CTG. Critical (reversed EDF, reversed DV a-wave): daily cCTG and/or DV Doppler. For an early FGR fetus at the 3rd centile with absent umbilical artery EDF (pre-critical), monitoring is on alternate days with umbilical artery Doppler, DV Doppler and cCTG. Timing of delivery in early FGR (gestational age up to 32 weeks): with AEDF or REDF in the UA, monitor every 2-3 days with cCTG and/or DV unless delivery is indicated; deliver if the DV a-wave is at or below baseline, or if short-term variation (STV) is below threshold (<2.6 ms at 26+0 to 28+6 weeks; <3.0 ms at 29+0 to 31+6 weeks).$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q128, p.75,76$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,$mmqz$[{"url": "/uploads/content-images/emrcog0224-q130-fig1.png", "caption": "Figure 1"}, {"url": "/uploads/content-images/emrcog0224-q130-fig2.png", "caption": "Figure 2"}]$mmqz$::jsonb,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q131$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$Early-onset FGR with reversed EDF. How will you monitor?$mmqz$,$mmqz$[{"label": "A", "text": "Daily cCTG"}, {"label": "B", "text": "Daily DV doppler"}, {"label": "C", "text": "Alternate every 2-3 days: DV doppler"}, {"label": "D", "text": "Alternate every 2-3 days: umbilical artery doppler"}]$mmqz$::jsonb,$mmqz$Daily cCTG$mmqz$,$mmqz$Umbilical artery Doppler changes are defined as: PI above the 95th centile (borderline), absent end-diastolic flow (EDF) (pre-critical) and reversed EDF (critical). Ductus venosus Doppler changes are defined as: PIV raised above the 95th centile (borderline), absent 'a' wave to baseline (pre-critical) or reversed 'a' wave (critical). Depending on severity, repeat ultrasound (umbilical and ductus venosus Doppler) and CTG monitoring is normally undertaken every week where umbilical Doppler changes are borderline, alternating daily in early-onset FGR with pre-critical umbilical Doppler changes. Where the umbilical Doppler changes are critical (reversed EDF), daily cCTG and/or ductus venosus Doppler are indicated, as sudden deterioration of the fetal condition may occur.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q129, p.77$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,$mmqz$[{"url": "/uploads/content-images/emrcog0224-q131-fig1.png", "caption": "Figure 1"}]$mmqz$::jsonb,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q132$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$Patient comes for booking. Her TPPA is positive, RPR negative, with a past history of syphilis. How will you manage this patient?$mmqz$,$mmqz$[{"label": "A", "text": "Treat for syphilis since RPR is false negative"}, {"label": "B", "text": "Reassure her as this is previously treated syphilis"}, {"label": "C", "text": "Retest again since this is early syphilis"}]$mmqz$::jsonb,$mmqz$Reassure her as this is previously treated syphilis$mmqz$,$mmqz$A positive TPPA (treponemal test) with a negative RPR (non-treponemal test) in a patient with a past history of syphilis indicates previously treated (or resolved) syphilis, so reassure. Treponemal tests (EIA, TP-PA/TPPA) detect syphilis-specific antibodies, are reported as reactive/non-reactive and remain positive over time in most cases (used for new diagnosis and screening). Non-treponemal tests (RPR, VDRL) detect antibodies released due to infection, are reported as a quantitative titre (higher titres indicate a stronger positive) and decline over time (faster with treatment), and are used to monitor treatment response and distinguish re-infection from resolved infection. On serology interpretation, a reactive treponemal test with a non-reactive RPR is consistent with previously treated syphilis (or early syphilis where RPR is not yet positive); with a documented history of treated syphilis, reassurance is appropriate.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q130, p.77$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,$mmqz$[{"url": "/uploads/content-images/emrcog0224-q132-fig1.png", "caption": "Figure 1"}]$mmqz$::jsonb,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q133$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$How will you manage a case of early syphilis diagnosed at 33 weeks of pregnancy?$mmqz$,$mmqz$[{"label": "A", "text": "Benzathine penicillin 2.4 mu im single dose"}, {"label": "B", "text": "Benzathine penicillin 2.4 mu im 2 doses"}, {"label": "C", "text": "Benzathine penicillin 2.4 mu im 3 doses"}, {"label": "D", "text": "Benzathine penicillin 2.4 mu im weekly for 2 doses"}, {"label": "E", "text": "Benzathine penicillin 2.4 mu im weekly for 3 doses"}]$mmqz$::jsonb,$mmqz$Benzathine penicillin 2.4 mu im weekly for 2 doses$mmqz$,$mmqz$Benzathine penicillin is the treatment for syphilis in pregnancy, with the regimen depending on trimester and stage. First/second trimester: early disease (primary/secondary or latent <2 years) is 2.4 MU IM as a single dose, and late disease (latent/unknown duration) is 2.4 MU IM weekly for 3 weeks/doses. Third trimester: early disease is 2.4 MU IM weekly for 2 weeks/doses, and the weekly regimen is used for late disease at all stages of pregnancy. Early syphilis diagnosed at 33 weeks (third trimester) is therefore treated with benzathine penicillin 2.4 MU IM weekly for 2 doses.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q131, p.78$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,$mmqz$[{"url": "/uploads/content-images/emrcog0224-q133-fig1.png", "caption": "Figure 1"}]$mmqz$::jsonb,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q134$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$What is the diagnostic marker for myocardial infarction in pregnancy?$mmqz$,$mmqz$[{"label": "A", "text": "Troponin"}, {"label": "B", "text": "CKMB"}, {"label": "C", "text": "Myoglobin"}, {"label": "D", "text": "creatinine kinase"}]$mmqz$::jsonb,$mmqz$Troponin$mmqz$,$mmqz$Cardiac-specific troponin I and troponin T are the biomarkers of choice for diagnosing myocardial infarction. Recommended sampling times vary by assay, so local guidelines should be checked; a negative troponin at presentation does not exclude cardiac damage as it can take up to 12 hours for the level to peak. Troponin is not raised above the upper limit of normal in healthy pregnant women and is not affected by anaesthesia, prolonged labour or caesarean section, and is therefore the investigation of choice. In contrast, myoglobin, creatinine kinase and CK-MB can be increased significantly in labour. Troponin can be mildly raised in pre-eclampsia, gestational hypertension and pulmonary embolism in the absence of significant coronary disease, but in pre-eclampsia the troponin level is never above the standard threshold set for MI.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q132, p.78$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,$mmqz$[{"url": "/uploads/content-images/emrcog0224-q134-fig1.png", "caption": "Figure 1"}]$mmqz$::jsonb,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q135$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$What is the diagnostic marker of choice in anaphylaxis?$mmqz$,$mmqz$[{"label": "A", "text": "Mast cell tryptase levels"}, {"label": "B", "text": "Eosinophil count"}, {"label": "C", "text": "Skin prick tests"}, {"label": "D", "text": "IgE estimation"}]$mmqz$::jsonb,$mmqz$Mast cell tryptase levels$mmqz$,$mmqz$Mast cell tryptase levels are the diagnostic marker of choice in anaphylaxis. Anaphylaxis is a clinical diagnosis suggested by sudden onset and rapid progression of symptoms, life-threatening airway and/or breathing and/or circulation problems, and skin and/or mucosal changes (flushing, urticaria, angioedema). Exposure to a known allergen supports the diagnosis, but many cases occur with no previous history. Mast cell tryptase can help confirm the diagnosis: as a minimum, one sample should be taken 1-2 hours after the start of symptoms; ideally three timed samples are taken - as soon as possible after resuscitation has started (without delaying resuscitation), 1-2 hours after symptom onset, and 24 hours later.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q133, p.79$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,$mmqz$[{"url": "/uploads/content-images/emrcog0224-q135-fig1.png", "caption": "Figure 1"}]$mmqz$::jsonb,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q136$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$Antenatal woman with a BMI of 34, at 40 weeks of gestation, came for ANC with mild dyspnoea. Examination showed SFH 46 cm. USG showed high-normal liquor and EFW 3.6 kg. What to do?$mmqz$,$mmqz$[{"label": "A", "text": "cs"}, {"label": "B", "text": "amniocentesis"}, {"label": "C", "text": "admit"}, {"label": "D", "text": "wait for spontaneous onset of labour"}, {"label": "E", "text": "induce"}, {"label": "F", "text": "measure fasting glucose/ OGTT"}, {"label": "G", "text": "measure oral glucose tolerance before deciding on the mode of delivery"}]$mmqz$::jsonb,$mmqz$measure oral glucose tolerance before deciding on the mode of delivery$mmqz$,$mmqz$The large symphysis-fundal height (46 cm at 40 weeks), high-normal liquor and estimated fetal weight of 3.6 kg in a woman with a raised BMI raise suspicion of macrosomia/LGA and gestational diabetes, so an oral glucose tolerance test should be arranged before deciding on the mode of delivery. Polyhydramnios can be defined with gestational-age-specific thresholds, but generally a constant value of AFI >=25 cm or DVP >=8 cm is used across all gestational ages; by AFI it is classified as mild (25.0-29.9 cm), moderate (30-34.9 cm) or severe (>35 cm). Pathway for suspected LGA/macrosomia: SFH >90th centile leads to considering USS; if LGA/macrosomia is diagnosed, offer OGTT (refer to the diabetic team if positive), explain the limitations of USS in predicting LGA, discuss the potential risks of LGA for mother and baby, then discuss management options (expectant management, induction of labour, or caesarean section).$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q134, p.79,80$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,$mmqz$[{"url": "/uploads/content-images/emrcog0224-q136-fig1.png", "caption": "Figure 1"}]$mmqz$::jsonb,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q137$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$A woman in her postpartum, who returned from a tropical country, brought in a baby with multiple skin pigments, microcephaly and hypoplasia of a limb. She had a fever with a vesicular rash in the earlier part of her pregnancy. What is the probable cause?$mmqz$,$mmqz$[{"label": "A", "text": "Herpes simplex virus"}, {"label": "B", "text": "Chicken pox"}, {"label": "C", "text": "Parvo virus"}, {"label": "D", "text": "Syphilis"}, {"label": "E", "text": "CMV"}]$mmqz$::jsonb,$mmqz$Chicken pox$mmqz$,$mmqz$Maternal varicella (chickenpox) or serological conversion in the first 28 weeks of pregnancy carries a small risk of fetal varicella syndrome (FVS), and the woman should be informed of the implications. FVS is characterised by one or more of: skin scarring in a dermatomal distribution; eye defects (microphthalmia, chorioretinitis or cataracts); hypoplasia of the limbs; and neurological abnormalities (microcephaly, cortical atrophy, mental retardation, or dysfunction of the bowel and bladder sphincters). FVS does not occur at the time of the initial fetal infection but results from a subsequent herpes zoster reactivation in utero, and occurs in only a minority of infected fetuses. A vesicular rash in early pregnancy with a baby showing skin scarring/pigmentation, microcephaly and limb hypoplasia is therefore due to varicella (chickenpox) rather than HSV, parvovirus, syphilis or CMV.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q135, p.80,81$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,NULL,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q138$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$Postmenopausal woman came with a complaint of bleeding per vagina for two weeks. Hysteroscopy and endometrial biopsy was done. Biopsy revealed hyperplasia without atypia in a polyp and the endometrium was normal (no hyperplasia). What is the management?$mmqz$,$mmqz$[{"label": "A", "text": "No further treatment"}, {"label": "B", "text": "Follow up with endometrial sampling 3 months"}, {"label": "C", "text": "Follow up with endometrial sampling 6 months"}]$mmqz$::jsonb,$mmqz$No further treatment$mmqz$,$mmqz$Endometrial hyperplasia confined to an endometrial polyp: complete removal of the uterine polyp(s) is recommended and an endometrial biopsy should be obtained to sample the background endometrium; subsequent management is according to the histological classification of the endometrial hyperplasia. Here the hyperplasia without atypia was confined to the polyp, which has been removed, and the background endometrium was normal (no hyperplasia), so no further treatment is required.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q136, p.81$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,$mmqz$[{"url": "/uploads/content-images/emrcog0224-q138-fig1.png", "caption": "Figure 1"}]$mmqz$::jsonb,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q139$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$How will you follow up a complete molar pregnancy following evacuation? Her hCG has reverted to normal within 56 days.$mmqz$,$mmqz$[{"label": "A", "text": "Follow up 6 months from the day of evacuation"}, {"label": "B", "text": "Follow up 6 months from the day of normal beta hCG"}, {"label": "C", "text": "Discharge after two samples normal 4 weeks apart"}]$mmqz$::jsonb,$mmqz$Follow up 6 months from the day of evacuation$mmqz$,$mmqz$For a complete molar pregnancy, if hCG has reverted to normal within 56 days of the pregnancy event, follow-up is for 6 months from the date of uterine evacuation. If hCG has not reverted to normal within 56 days of the pregnancy event, follow-up is for 6 months from normalisation of the hCG level. Follow-up for a partial molar pregnancy is concluded once hCG has returned to normal on two samples at least 4 weeks apart. As this complete mole normalised within 56 days, follow-up is 6 months from the day of evacuation.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q137, p.81$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,$mmqz$[{"url": "/uploads/content-images/emrcog0224-q139-fig1.png", "caption": "Figure 1"}]$mmqz$::jsonb,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q140$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$Bicornuate uterus is associated with which of the following?$mmqz$,$mmqz$[{"label": "A", "text": "Pregnancy loss"}, {"label": "B", "text": "Malpresentation"}, {"label": "C", "text": "Ectopic pregnancy"}, {"label": "D", "text": "Labour dystocia"}]$mmqz$::jsonb,$mmqz$Malpresentation$mmqz$,$mmqz$Unification defects such as bicornuate, unicornuate and didelphic uteri do not appear to reduce fertility but are associated with increased risks of adverse pregnancy outcomes, depending on the type of defect. Women with bicornuate and unicornuate uteri have an increased risk of first-trimester miscarriage (OR 3.4 and OR 2.15), preterm birth (OR 2.55 and OR 3.47) and fetal malpresentation (OR 5.38 and OR 2.74); women with uterus didelphys have an increased risk of preterm labour (OR 3.58) and fetal malpresentation (OR 3.7). The strongest association for a bicornuate uterus is with fetal malpresentation (OR 5.38).$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q138, p.81,82$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,$mmqz$[{"url": "/uploads/content-images/emrcog0224-q140-fig1.png", "caption": "Figure 1"}]$mmqz$::jsonb,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q141$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$Woman is counselled regarding endometrial hyperplasia without atypia. What is the risk of progression to cancer?$mmqz$,$mmqz$[{"label": "A", "text": "1-5 % over 20 years"}, {"label": "B", "text": "10% over 20 years"}, {"label": "C", "text": "15% over 20 years"}, {"label": "D", "text": "25% over 20 years"}, {"label": "E", "text": "30% over 20 years"}]$mmqz$::jsonb,$mmqz$1-5 % over 20 years$mmqz$,$mmqz$A 20-year follow-up study found that among women with hyperplasia without atypia (previously described as simple or complex hyperplasia), the cumulative long-term risk of progression to endometrial cancer is less than 5% over 20 years.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q139, p.82$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,NULL,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
INSERT INTO mcqs (id,topic_id,question,options,correct_answer,explanation,option_explanations,difficulty,"references",tags,images,is_published,created_at,updated_at) VALUES ($mmqz$emrcog-jul2024-02-q142$mmqz$,$mmqz$emrcog-jul2024-02-topic$mmqz$,$mmqz$What is the risk of CTPA over V/Q scan?$mmqz$,$mmqz$[{"label": "A", "text": "Higher risk of childhood cancer"}, {"label": "B", "text": "Higher risk of maternal breast cancer"}]$mmqz$::jsonb,$mmqz$Higher risk of maternal breast cancer$mmqz$,$mmqz$While CTPA is associated with a low radiation risk to the fetus, it delivers a relatively high radiation dose (up to 20 mGy) to the mother's breast tissue, which is associated with an increased risk of breast cancer; the dose estimate for CTPA is 20 to 100 times greater than for V/Q scanning. The dose depends on breast size, the technique used and the woman's age (the risk being greater in younger women). Breast doses from CTPA can be reduced by 20-40% using bismuth shields placed over the breasts. Lung perfusion (V/Q) scanning should be considered the investigation of first choice for young women, especially if there is a family history of breast cancer or a previous chest CT scan.$mmqz$,NULL,$mmqz$medium$mmqz$,$mmqz$MRCOG Recalls July 2024 (Paper 02), source Q140, p.82$mmqz$,$mmqz$["MRCOG", "EMRCOG", "Recalls", "July 2024", "Paper 02"]$mmqz$::jsonb,NULL,true,now(),now()) ON CONFLICT (id) DO UPDATE SET question=EXCLUDED.question,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,explanation=EXCLUDED.explanation,difficulty=EXCLUDED.difficulty,"references"=EXCLUDED."references",tags=EXCLUDED.tags,images=EXCLUDED.images,is_published=EXCLUDED.is_published,updated_at=now();
